test "qkv verify kernel parity: multi-block split-KV merge (T_k > BLOCK)" {
    if (!mlx.metalKernelsAvailable()) return error.SkipZigTest;
    // GQA 4 x TQ 2 → BLOCK 256; 700+2 rows exercises the multi-block carry,
    // including a final block whose tail rows are causally -inf for tq 0.
    try qkvVerParityCase(8, 2, 64, 8, 700, 2);
    try qkvVerParityCase(8, 2, 128, 8, 700, 6);
}

test "qkv verify kernel declines non-verify widths and foreign masks" {
    // Exercise the kernel's own decline predicates even where the machine
    // adoption default declines the entire arm first.
    const old_qkv_ver_override = qkv_ver_override;
    qkv_ver_override = true;
    defer qkv_ver_override = old_qkv_ver_override;
    const s = mlx.gpuStream();
    var view: DenseKVView = .{ .k = .{ .ctx = null }, .v = .{ .ctx = null }, .owned = false, .has_quant_triple = false };
    const shape = [_]c_int{ 1, 4, 2, 64 };
    var q2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q2);
    try mlx.check(mlx.mlx_ones(&q2, &shape, 4, .bfloat16, s));
    // no triple → decline regardless of width
    try testing.expectEqual(@as(?mlx.mlx_array, null), try qkvAttnVerifyKernel(s, q2, &view, 1.0, "causal"));
    // real triple, wrong widths / modes
    var cache = try KVCache.initWithConfig(testing.allocator, 1, kv_quant.KVQuantConfig.affine(8));
    defer cache.deinit();
    const kshape = [_]c_int{ 1, 2, 40, 64 };
    var kv = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kv);
    try mlx.check(mlx.mlx_ones(&kv, &kshape, 4, .bfloat16, s));
    var dv = try cache.update(0, kv, kv, s, 0);
    defer dv.deinit();
    var q1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q1);
    const q1shape = [_]c_int{ 1, 4, 1, 64 };
    try mlx.check(mlx.mlx_ones(&q1, &q1shape, 4, .bfloat16, s));
    try testing.expectEqual(@as(?mlx.mlx_array, null), try qkvAttnVerifyKernel(s, q1, &dv, 1.0, "causal")); // T_q 1 belongs to the decode kernel
    var q9 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q9);
    const q9shape = [_]c_int{ 1, 4, QKV_VERIFY_MAX_TQ + 1, 64 };
    try mlx.check(mlx.mlx_ones(&q9, &q9shape, 4, .bfloat16, s));
    try testing.expectEqual(@as(?mlx.mlx_array, null), try qkvAttnVerifyKernel(s, q9, &dv, 1.0, "causal")); // past the width cap
    var q4 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q4);
    const q4shape = [_]c_int{ 1, 4, 4, 64 };
    try mlx.check(mlx.mlx_ones(&q4, &q4shape, 4, .bfloat16, s));
    try testing.expectEqual(@as(?mlx.mlx_array, null), try qkvAttnVerifyKernel(s, q4, &dv, 1.0, "array")); // sliding masks read dense
    try testing.expectEqual(@as(?mlx.mlx_array, null), try qkvAttnVerifyKernel(s, q4, &dv, 1.0, "")); // unmasked multi-row is not this kernel's contract
}

fn composedStridedCase(h_q: c_int, h_kv: c_int, d: c_int, bits: u8, t_pre: usize, t_chunk: c_int, mode: [:0]const u8) !void {
    const s = mlx.gpuStream();
    var cache = try KVCache.initWithConfig(testing.allocator, 1, kv_quant.KVQuantConfig.affine(bits));
    defer cache.deinit();
    const mk = struct {
        fn f(str: mlx.mlx_stream, hh: c_int, tt: c_int, dd: c_int, seed: f32) !mlx.mlx_array {
            const total: usize = @intCast(hh * tt * dd);
            const buf = try testing.allocator.alloc(f32, total);
            defer testing.allocator.free(buf);
            for (buf, 0..) |*x, i| x.* = @sin(@as(f32, @floatFromInt(i)) * 0.31 + seed) * 0.7;
            const shape = [_]c_int{ 1, hh, tt, dd };
            const f32_arr = mlx.mlx_array_new_data(buf.ptr, &shape, 4, .float32);
            defer _ = mlx.mlx_array_free(f32_arr);
            var bf = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_astype(&bf, f32_arr, .bfloat16, str));
            return bf;
        }
    }.f;
    if (t_pre > 0) {
        const k = try mk(s, h_kv, @intCast(t_pre), d, 0.2);
        defer _ = mlx.mlx_array_free(k);
        const v = try mk(s, h_kv, @intCast(t_pre), d, 1.1);
        defer _ = mlx.mlx_array_free(v);
        var dv0 = try cache.update(0, k, v, s, 0);
        dv0.deinit();
    }
    const k1 = try mk(s, h_kv, t_chunk, d, 2.3);
    defer _ = mlx.mlx_array_free(k1);
    const v1 = try mk(s, h_kv, t_chunk, d, 3.7);
    defer _ = mlx.mlx_array_free(v1);
    var dv = try cache.update(0, k1, v1, s, 0);
    defer dv.deinit();
    try testing.expect(dv.has_quant_triple);

    const t_k: c_int = @as(c_int, @intCast(t_pre)) + t_chunk;
    const q = try mk(s, h_q, t_chunk, d, 5.5);
    defer _ = mlx.mlx_array_free(q);
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(d)));

    // Optional additive mask (sliding-window prefill shape).
    var mask = mlx.mlx_array{ .ctx = null };
    defer if (mask.ctx != null) {
        _ = mlx.mlx_array_free(mask);
    };
    if (std.mem.eql(u8, mode, "array")) {
        const rows: usize = @intCast(t_chunk);
        const cols: usize = @intCast(t_k);
        const mbuf = try testing.allocator.alloc(f32, rows * cols);
        defer testing.allocator.free(mbuf);
        const off: usize = @intCast(t_k - t_chunk);
        for (0..rows) |r| {
            for (0..cols) |c| {
                // causal + band(3): visible iff c <= off+r and (off+r)-c < 3
                const vis = c <= off + r and (off + r) - c < 3;
                mbuf[r * cols + c] = if (vis) 0.0 else -std.math.inf(f32);
            }
        }
        const mshape = [_]c_int{ 1, 1, t_chunk, t_k };
        const mf32 = mlx.mlx_array_new_data(mbuf.ptr, &mshape, 4, .float32);
        defer _ = mlx.mlx_array_free(mf32);
        var mbf = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_astype(&mbf, mf32, .bfloat16, s));
        mask = mbf;
    }
    const none = mlx.mlx_array{ .ctx = null };
    const mask_used = if (mask.ctx != null) mask else none;

    var ref = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ref);
    try mlx.check(mlx.mlx_fast_scaled_dot_product_attention(&ref, q, dv.k, dv.v, scale, mode, mask_used, .{ .ctx = null }, false, s));

    const cand = try kv_quant.quantAttention(q, dv.kTriple(), dv.vTriple(), dv.bits, dv.group_size, scale, mode, mask_used, s);
    defer _ = mlx.mlx_array_free(cand);

    const readFlat = struct {
        fn f(str: mlx.mlx_stream, arr: mlx.mlx_array, allocator: std.mem.Allocator) ![]f32 {
            var f32v = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(f32v);
            try mlx.check(mlx.mlx_astype(&f32v, arr, .float32, str));
            const n: c_int = @intCast(mlx.mlx_array_size(f32v));
            var flat = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(flat);
            const sh = [_]c_int{n};
            try mlx.check(mlx.mlx_reshape(&flat, f32v, &sh, 1, str));
            const ev = mlx.mlx_vector_array_new();
            defer _ = mlx.mlx_vector_array_free(ev);
            _ = mlx.mlx_vector_array_append_value(ev, flat);
            try mlx.check(mlx.mlx_eval(ev));
            const ptr = mlx.mlx_array_data_float32(flat) orelse return error.NullData;
            const out = try allocator.alloc(f32, @intCast(n));
            @memcpy(out, ptr[0..@intCast(n)]);
            return out;
        }
    }.f;
    const ref_flat = try readFlat(s, ref, testing.allocator);
    defer testing.allocator.free(ref_flat);
    const cand_flat = try readFlat(s, cand, testing.allocator);
    defer testing.allocator.free(cand_flat);
    var max_err: f32 = 0;
    for (ref_flat, cand_flat) |r, c| {
        // NaN-blind comparisons pass on an all-NaN candidate (NaN > x is
        // false) - the composed causal arm shipped NaN for months behind
        // exactly this hole. Finiteness is asserted BEFORE the diff.
        try testing.expect(!std.math.isNan(c));
        const e = @abs(r - c);
        if (e > max_err) max_err = e;
    }
    if (max_err >= 0.05) std.debug.print("composedStridedCase Hq={d} Hkv={d} D={d} bits={d} pre={d} chunk={d} mode={s}: max_err={d}\n", .{ h_q, h_kv, d, bits, t_pre, t_chunk, mode, max_err });
    try testing.expect(max_err < 0.05);
}

test "composed quantAttention is correct on STRIDED cache views" {
    mlx.installErrorHandler(); // a shape MLX cannot run must fail, never abort
    // Class guard (splitPackedGateUp rule): slice-born views into
    // mlx_quantized_matmul must compute correctly - the cache's packed views
    // are non-contiguous whenever buffer capacity > logical length. Covers
    // multi-row widths, the gemma E4B live geometry (single 15-token chunk,
    // hd 256, 4-bit - the "<pad><pad>" shape), and the sliding "array" mask.
    // (Serving only routes t_q == 1 here since 2026-08-15, but the helper's
    // contract is width-agnostic and the strided-view class is the point.)
    try composedStridedCase(8, 2, 64, 4, 20, 4, "causal");
    try composedStridedCase(8, 2, 256, 4, 0, 15, "causal");
    try composedStridedCase(8, 2, 256, 4, 0, 15, "array");
    try composedStridedCase(8, 2, 256, 4, 20, 15, "array");
}

test "fused kv-quant serving arms are kernel-or-DENSE - composed attention never serves" {
    // gemma4-12B measured (2026-08-15, kv8, 11k ctx): composed reads at
    // t_q == 1 cost −17% decode on the full-attention layers where
    // `qkvAttnDecodeKernel` declines (gqa 16 x dk 512 overflows the
    // threadgroup q-staging budget), and Phase 1 already routes every other
    // width dense. So a declined kernel falls through to the dense SDPA
    // arms; the composed helper remains ONLY as the strided-view parity
    // reference (`composedStridedCase`).
    const src = @embedFile("transformer.zig");
    const needle = "kv_quant.quant" ++ "Attention(";
    try testing.expectEqual(@as(usize, 1), std.mem.count(u8, src, needle));
    const only = std.mem.indexOf(u8, src, needle).?;
    const helper = std.mem.indexOf(u8, src, "fn composedStridedCase(").?;
    try testing.expect(only > helper);
}

test "qkv decode kernel declines non-decode widths and missing triples" {
    const s = mlx.gpuStream();
    // T_q = 2 → decline (only decode width may reach the kernel).
    var view: DenseKVView = .{ .k = .{ .ctx = null }, .v = .{ .ctx = null }, .owned = false, .has_quant_triple = false };
    const shape = [_]c_int{ 1, 4, 2, 64 };
    var q2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q2);
    try mlx.check(mlx.mlx_ones(&q2, &shape, 4, .bfloat16, s));
    // No triple → decline regardless of shape.
    try testing.expectEqual(@as(?mlx.mlx_array, null), try qkvAttnDecodeKernel(s, q2, &view, 1.0, "", .{ .ctx = null }));
}

test "qkv packed-attention surface µbench (env-gated: MLX_SERVE_KVQ_UBENCH=1)" {
    // Per (t_q, kv): (a) packed kernel, (b) dequant + dense sdpa, (c) bf16
    // sdpa with no dequant. Arms interleave in one process and the cell order
    // reverses per pass; BATCH launches share one eval so the sync barrier
    // does not price the cell.
    if (!diagEnvOn("MLX_SERVE_KVQ_UBENCH")) return;
    const old_ver = qkv_ver_override;
    qkv_ver_override = true;
    defer qkv_ver_override = old_ver;
    const s = mlx.gpuStream();
    const io = std.Io.Threaded.global_single_threaded.io();
    const H_Q: c_int = 24;
    const H_KV: c_int = 4;
    const D: c_int = 256;
    const BITS: u8 = 8;
    const kvs = [_]usize{ 2048, 4096, 8192, 16384, 32768, 65536 };
    const tqs = [_]c_int{ 1, 2, 3, 4, 6, 8 };
    const PASSES = 4;
    const BATCH = 8;
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(D)));
    const none = mlx.mlx_array{ .ctx = null };

    const randBf16 = struct {
        fn f(str: mlx.mlx_stream, shape: []const c_int, sd: f32) !mlx.mlx_array {
            var tmp = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(tmp);
            try mlx.check(mlx.mlx_random_normal(&tmp, shape.ptr, shape.len, .float32, 0.0, sd, .{ .ctx = null }, str));
            var out = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_astype(&out, tmp, .bfloat16, str));
            return out;
        }
    }.f;

    std.debug.print("\n[kvq-surface] Hq={d} Hkv={d} D={d} bits={d}\n[kvq-surface] {s:>6} {s:>3} {s:>9} {s:>9} {s:>9} {s:>9}\n", .{ H_Q, H_KV, D, BITS, "kv", "tq", "packed", "dq+sdpa", "bf16", "mpp" });
    for (kvs) |kv| {
        var ns: [tqs.len][4]u64 = @splat(@splat(0));
        for (tqs, 0..) |tq, ti| {
            // Own cache per width: the verify contract has the tq rows appended.
            var cache = try KVCache.initWithConfig(testing.allocator, 1, kv_quant.KVQuantConfig.affine(BITS));
            defer cache.deinit();
            {
                const k = try randBf16(s, &[_]c_int{ 1, H_KV, @intCast(kv - @as(usize, @intCast(tq))), D }, 0.2);
                defer _ = mlx.mlx_array_free(k);
                var dv0 = try cache.update(0, k, k, s, 0);
                dv0.deinit();
            }
            const k1 = try randBf16(s, &[_]c_int{ 1, H_KV, tq, D }, 0.2);
            defer _ = mlx.mlx_array_free(k1);
            var dv = try cache.update(0, k1, k1, s, 0);
            defer dv.deinit();
            var k_off = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(k_off);
            try mlx.check(mlx.mlx_contiguous(&k_off, dv.k, false, s));
            const q = try randBf16(s, &[_]c_int{ 1, H_Q, tq, D }, 0.5);
            defer _ = mlx.mlx_array_free(q);
            {
                const ev = mlx.mlx_vector_array_new();
                defer _ = mlx.mlx_vector_array_free(ev);
                _ = mlx.mlx_vector_array_append_value(ev, k_off);
                _ = mlx.mlx_vector_array_append_value(ev, q);
                try mlx.check(mlx.mlx_eval(ev));
            }
            const mode: [:0]const u8 = if (tq == 1) "" else "causal";

            for (0..PASSES + 1) |pass| { // pass 0 = warmup
                for (0..4) |a0| {
                    const arm = if (pass % 2 == 0) a0 else 3 - a0;
                    const ev = mlx.mlx_vector_array_new();
                    defer _ = mlx.mlx_vector_array_free(ev);
                    const mark = std.Io.Timestamp.now(io, .boot);
                    for (0..BATCH) |_| {
                        var out = mlx.mlx_array_new();
                        defer _ = mlx.mlx_array_free(out);
                        switch (arm) {
                            0 => out = (if (tq == 1)
                                try qkvAttnDecodeKernel(s, q, &dv, scale, "", none)
                            else
                                try qkvAttnVerifyKernel(s, q, &dv, scale, "causal")) orelse return error.KernelDeclined,
                            3 => out = (try qkvAttnMppKernel(s, q, &dv, scale, mode)) orelse return error.KernelDeclined,
                            else => {
                                var kd = k_off;
                                if (arm == 1) kd = try kv_quant.dequantizeAffine(s, dv.k_triple_q, dv.k_triple_scales, dv.k_triple_biases, dv.group_size, dv.bits);
                                defer if (arm == 1) {
                                    _ = mlx.mlx_array_free(kd);
                                };
                                var vd = k_off;
                                if (arm == 1) vd = try kv_quant.dequantizeAffine(s, dv.v_triple_q, dv.v_triple_scales, dv.v_triple_biases, dv.group_size, dv.bits);
                                defer if (arm == 1) {
                                    _ = mlx.mlx_array_free(vd);
                                };
                                if (tq > 1) {
                                    if (try splitCausalSdpa(s, q, kd, vd, scale)) |sp| out = sp;
                                }
                                if (out.ctx == null) try mlx.check(mlx.mlx_fast_scaled_dot_product_attention(&out, q, kd, vd, scale, mode.ptr, none, .{ .ctx = null }, false, s));
                            },
                        }
                        _ = mlx.mlx_vector_array_append_value(ev, out);
                    }
                    try mlx.check(mlx.mlx_eval(ev));
                    if (pass > 0) ns[ti][arm] += @intCast(mark.untilNow(io, .boot).nanoseconds);
                }
            }
            _ = mlx.mlx_clear_cache();
        }
        for (tqs, 0..) |tq, ti| {
            var ms: [4]f64 = undefined;
            for (&ms, 0..) |*m, a| m.* = @as(f64, @floatFromInt(ns[ti][a])) / @as(f64, PASSES * BATCH) / 1e6;
            std.debug.print("[kvq-surface] {d:>6} {d:>3} {d:>9.3} {d:>9.3} {d:>9.3} {d:>9.3}\n", .{ kv, tq, ms[0], ms[1], ms[2], ms[3] });
        }
    }
}

test "kvAttnFusedEligible: fused reads are decode-width (t_q == 1) only" {
    // This is the explicit verify-kernel eligibility arm. G17's production
    // default is dense, so force the QA seam before testing width/floor rules.
    const old_qkv_ver_override = qkv_ver_override;
    qkv_ver_override = true;
    defer qkv_ver_override = old_qkv_ver_override;
    // The ONE gate every fused call site reads. Verify widths (T_q 2..32
    // under spec) used to be admitted and fell to the composed qmm
    // chain - a deliberate choice that predates deep speculative defaults and was
    // never A/B'd at spec depth. Measured (M4 Max, 2026-08-15, 8k+ ctx,
    // deep spec round): 28 tok/s decode vs 60 on the dense read - the
    // composed chain runs 2 packed matmuls x every attention layer per spec
    // round, at qmm's M 2..7 dead zone. Decode width keeps the packed-read
    // kernel win; every other width reads the dense view (the reference
    // semantics). Short-KV layers (sliding windows) stay dense too: the
    // kernel's split-KV merge overhead measured a net loss there.
    const s = mlx.gpuStream();
    const long_shape = [_]c_int{ 1, 2, KV_ATTN_FUSED_MIN_TK, 16 };
    var kq_long = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kq_long);
    try mlx.check(mlx.mlx_zeros(&kq_long, &long_shape, 4, .uint32, s));
    const short_shape = [_]c_int{ 1, 2, 512, 16 };
    var kq_short = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kq_short);
    try mlx.check(mlx.mlx_zeros(&kq_short, &short_shape, 4, .uint32, s));

    var view_with: DenseKVView = .{ .k = .{ .ctx = null }, .v = .{ .ctx = null }, .owned = false, .has_quant_triple = true, .k_triple_q = kq_long };
    var view_short: DenseKVView = .{ .k = .{ .ctx = null }, .v = .{ .ctx = null }, .owned = false, .has_quant_triple = true, .k_triple_q = kq_short };
    var view_without: DenseKVView = .{ .k = .{ .ctx = null }, .v = .{ .ctx = null }, .owned = false, .has_quant_triple = false };
    try testing.expect(kvAttnFusedEligible(&view_with, 1));
    try testing.expect(!kvAttnFusedEligible(&view_with, 2)); // verify width
    try testing.expect(!kvAttnFusedEligible(&view_with, 9));
    try testing.expect(!kvAttnFusedEligible(&view_with, 32));
    try testing.expect(!kvAttnFusedEligible(&view_with, 2048)); // prefill width
    try testing.expect(!kvAttnFusedEligible(&view_short, 1)); // below the kv floor
    try testing.expect(!kvAttnFusedEligible(&view_without, 1));
    // Phase 2: verify widths (2..QKV_VERIFY_MAX_TQ) have their OWN gate,
    // serving the TQ-wide packed kernel - never the composed chain.
    try testing.expect(!kvAttnVerifyEligible(&view_with, 1)); // decode belongs to the decode kernel
    try testing.expect(kvAttnVerifyEligible(&view_with, 2));
    try testing.expect(kvAttnVerifyEligible(&view_with, QKV_VERIFY_MAX_TQ));
    try testing.expect(!kvAttnVerifyEligible(&view_with, QKV_VERIFY_MAX_TQ + 1)); // prefill chunks stay dense
    try testing.expect(!kvAttnVerifyEligible(&view_short, 4)); // below the kv floor
    try testing.expect(!kvAttnVerifyEligible(&view_without, 4));
}

test "KVCache step resets on truncate" {
    const s = mlx.gpuStream();
    var cache = try KVCache.init(testing.allocator, 1);
    defer cache.deinit();

    // Add 5 tokens
    {
        const k = testKV(5, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(5, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(0, k, v, s, 0);
    }
    try testing.expectEqual(@as(usize, 5), cache.step);

    // Truncate to 3 (simulating KV cache reuse)
    try cache.truncate(3, s);
    try testing.expectEqual(@as(usize, 3), cache.entries[0].offset);
    try testing.expectEqual(@as(usize, 3), cache.step);
}

test "KVCache step without trimming matches offset" {
    const s = mlx.gpuStream();
    var cache = try KVCache.init(testing.allocator, 1);
    defer cache.deinit();

    // Add tokens without max_seq (no trimming)
    for (0..10) |_| {
        const k = testKV(1, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(1, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(0, k, v, s, 0);
    }
    // Without trimming, step and offset should be equal
    try testing.expectEqual(@as(usize, 10), cache.entries[0].offset);
    try testing.expectEqual(@as(usize, 10), cache.step);
}

test "kvLenForBatching: the batched cap reads the ATTENTION layers, never layer 0's step" {
    // `KVCache.step` advances on global layer 0 only, so on a linear-layer-0 trunk it reads 0
    // forever; the probe is "is entry 0 initialized?", not an arch list.
    const families = [_]struct { layers: u32, first_attn: u32, len: usize }{
        .{ .layers = 48, .first_attn = 3, .len = 60_000 }, // a hybrid trunk whose layer 0 is not attention
        .{ .layers = 32, .first_attn = 7, .len = 131_072 },
    };
    for (families) |f| {
        var cache = try KVCache.init(testing.allocator, f.layers);
        defer cache.deinit();
        var li = f.first_attn;
        while (li < f.layers) : (li += 4) {
            cache.entries[li].initialized = true;
            cache.entries[li].offset = f.len;
        }
        try testing.expectEqual(@as(usize, 0), cache.step); // the trap
        try testing.expectEqual(f.len, cache.kvLenForBatching());
    }

    // Attention-first trunk: `step` stays the answer.
    var attn = try KVCache.init(testing.allocator, 4);
    defer attn.deinit();
    attn.step = 4096;
    attn.entries[0].initialized = true;
    attn.entries[0].offset = 4096;
    try testing.expectEqual(@as(usize, 4096), attn.kvLenForBatching());

    var cold = try KVCache.init(testing.allocator, 4);
    defer cold.deinit();
    try testing.expectEqual(@as(usize, 0), cold.kvLenForBatching());
}

test "KVCache step with multi-layer only increments once per update" {
    const s = mlx.gpuStream();
    var cache = try KVCache.init(testing.allocator, 3);
    defer cache.deinit();

    // Update all 3 layers with 2 tokens each
    for (0..3) |layer| {
        const k = testKV(2, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(2, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(@intCast(layer), k, v, s, 0);
    }
    // step should be 2 (one sequence worth), not 6 (3 layers × 2)
    try testing.expectEqual(@as(usize, 2), cache.step);
}

// ── Cache snapshot/restore (for spec-decode rollback) ──────────────────────

test "KVCache snapshot/restore round-trip preserves entries and step" {
    const s = mlx.gpuStream();
    var cache = try KVCache.init(testing.allocator, 2);
    defer cache.deinit();

    // Build state: 4 tokens across 2 layers.
    for (0..2) |layer| {
        const k = testKV(4, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(4, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(@intCast(layer), k, v, s, 0);
    }
    try testing.expectEqual(@as(usize, 4), cache.step);
    try testing.expectEqual(@as(usize, 4), cache.entries[0].offset);

    // Snapshot at this point.
    var snap = try cache.snapshot();
    defer snap.deinit();

    // Mutate cache: add 2 more tokens to layer 0 only (to verify per-layer
    // offset is captured, not just global step).
    {
        const k = testKV(2, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(2, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(0, k, v, s, 0);
    }
    try testing.expectEqual(@as(usize, 6), cache.step);
    try testing.expectEqual(@as(usize, 6), cache.entries[0].offset);

    // Restore - step and per-layer offsets revert to snapshot.
    try cache.restore(&snap);
    try testing.expectEqual(@as(usize, 4), cache.step);
    try testing.expectEqual(@as(usize, 4), cache.entries[0].offset);
    try testing.expectEqual(@as(usize, 4), cache.entries[1].offset);
}

test "KVCache snapshot then more updates does not corrupt the snapshot" {
    // Critical invariant for spec-decode rollback: if we snapshot, then verify, then
    // (rejected) restore, snapshot must NOT have been mutated by the intervening
    // updates. The buffer is shared via refcount but must not be aliased through
    // the cache entry pointer.
    const s = mlx.gpuStream();
    var cache = try KVCache.init(testing.allocator, 1);
    defer cache.deinit();

    {
        const k = testKV(2, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(2, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(0, k, v, s, 0);
    }

    var snap = try cache.snapshot();
    defer snap.deinit();
    try testing.expectEqual(@as(usize, 2), snap.entries[0].offset);

    // Run several updates to grow the cache buffer (forces buffer reallocation
    // inside update(), which would invalidate a naive snapshot).
    for (0..6) |_| {
        const k = testKV(1, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(1, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(0, k, v, s, 0);
    }
    try testing.expectEqual(@as(usize, 8), cache.entries[0].offset);

    // Snapshot still reports its captured state.
    try testing.expectEqual(@as(usize, 2), snap.entries[0].offset);
    try testing.expectEqual(@as(usize, 2), snap.step);

    try cache.restore(&snap);
    try testing.expectEqual(@as(usize, 2), cache.entries[0].offset);
    try testing.expectEqual(@as(usize, 2), cache.step);
}

test "KVCache: an append after a short restore sizes its copy from the prefix, not the donor (#492)" {
    // A 4k "hi" session restored from an 80k agent session's entry kept an 80k-capacity copy,
    // and its commit evicted the agent session to fit the budget.
    const s = mlx.gpuStream();
    const mk = struct {
        fn f(str: mlx.mlx_stream, len: c_int) !mlx.mlx_array {
            const shape = [_]c_int{ 1, 2, len, 64 };
            var a = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_ones(&a, &shape, 4, .bfloat16, str));
            return a;
        }
    }.f;
    for ([_]kv_quant.KVQuantConfig{ kv_quant.KVQuantConfig.dense, kv_quant.KVQuantConfig.affine(8) }) |cfg| {
        var donor = try KVCache.initWithConfig(testing.allocator, 1, cfg);
        defer donor.deinit();
        {
            const k = try mk(s, 8192);
            defer _ = mlx.mlx_array_free(k);
            _ = try donor.update(0, k, k, s, 0);
        }
        var snap = try donor.snapshot();
        defer snap.deinit();

        var cache = try KVCache.initWithConfig(testing.allocator, 1, cfg);
        defer cache.deinit();
        try cache.restore(&snap);
        try cache.truncate(100, s);
        const k = try mk(s, 1);
        defer _ = mlx.mlx_array_free(k);
        _ = try cache.update(0, k, k, s, 0);

        try testing.expectEqual(@as(usize, 101), cache.entries[0].offset);
        try testing.expect(KVCache.bufferCapacity(cache.entries[0].keys) <= 512);
        try testing.expect(KVCache.bufferCapacity(snap.entries[0].keys) >= 8192);
    }
}

test "KVCache.compactRows: a tree's accepted path lands as serial appends would, dense and quantized" {
    const s = mlx.gpuStream();
    const base: usize = 6;
    var key = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(key);
    try mlx.check(mlx.mlx_random_key(&key, 42));
    var xf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(xf);
    try mlx.check(mlx.mlx_random_normal(&xf, &[_]c_int{ 1, 2, base + 8, 64 }, 4, .float32, 0.0, 1.0, key, s));
    var x = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(x);
    try mlx.check(mlx.mlx_astype(&x, xf, .bfloat16, s));
    const rows = [_]u32{ 2, 5 };
    for ([_]kv_quant.KVQuantConfig{ kv_quant.KVQuantConfig.dense, kv_quant.KVQuantConfig.affine(8) }) |cfg| {
        var tree = try KVCache.initWithConfig(testing.allocator, 1, cfg);
        defer tree.deinit();
        _ = try tree.update(0, x, x, s, 0);
        try tree.compactRows(base, &rows, s);
        try tree.truncate(base + 1 + rows.len, s);

        var serial = try KVCache.initWithConfig(testing.allocator, 1, cfg);
        defer serial.deinit();
        const idx_host = [_]i32{ 0, 1, 2, 3, 4, 5, 6, @intCast(base + rows[0]), @intCast(base + rows[1]) };
        const idx = mlx.mlx_array_new_data(&idx_host, &[_]c_int{idx_host.len}, 1, .int32);
        defer _ = mlx.mlx_array_free(idx);
        var picked = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(picked);
        try mlx.check(mlx.mlx_take_axis(&picked, x, idx, 2, s));
        _ = try serial.update(0, picked, picked, s, 0);

        var a = try tree.denseView(0, s);
        defer a.deinit();
        var b = try serial.denseView(0, s);
        defer b.deinit();
        try testing.expectEqualSlices(c_int, mlx.getShape(b.k), mlx.getShape(a.k));
        for ([_][2]mlx.mlx_array{ .{ a.k, b.k }, .{ a.v, b.v } }) |pair| {
            var eq = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(eq);
            try mlx.check(mlx.mlx_array_equal(&eq, pair[0], pair[1], false, s));
            var same = false;
            try mlx.check(mlx.mlx_array_item_bool(&same, eq));
            try testing.expect(same);
        }
    }
}

test "KVCache snapshot/restore in a tight loop does not leak" {
    // testing.allocator is a TrackingAllocator - any unfreed allocation here
    // surfaces as a test failure at the leak-detection step.
    const s = mlx.gpuStream();
    var cache = try KVCache.init(testing.allocator, 2);
    defer cache.deinit();

    {
        const k = testKV(3, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(3, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(0, k, v, s, 0);
        const k2 = testKV(3, s);
        defer _ = mlx.mlx_array_free(k2);
        const v2 = testKV(3, s);
        defer _ = mlx.mlx_array_free(v2);
        _ = try cache.update(1, k2, v2, s, 0);
    }

    var i: usize = 0;
    while (i < 50) : (i += 1) {
        var snap = try cache.snapshot();
        defer snap.deinit();
        const k = testKV(1, s);
        defer _ = mlx.mlx_array_free(k);
        const v = testKV(1, s);
        defer _ = mlx.mlx_array_free(v);
        _ = try cache.update(0, k, v, s, 0);
        try cache.restore(&snap);
    }
}

const kv_append_kv_h: c_int = 2;
const kv_append_hd: c_int = 256;

fn kvAppendPacked(n: c_int, seq: c_int, seed: u32, s: mlx.mlx_stream) !mlx.mlx_array {
    const nn: usize = @intCast(n * kv_append_kv_h * seq * kv_append_hd);
    const buf = try testing.allocator.alloc(f32, nn);
    defer testing.allocator.free(buf);
    var st: u32 = seed;
    for (buf) |*x| {
        st = st *% 1664525 +% 1013904223;
        x.* = @as(f32, @floatFromInt(st >> 16)) / 65536.0 - 0.5;
    }
    const shape = [_]c_int{ n, kv_append_kv_h, seq, kv_append_hd };
    const f32_arr = mlx.mlx_array_new_data(buf.ptr, &shape, 4, .float32);
    defer _ = mlx.mlx_array_free(f32_arr);
    var out = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_astype(&out, f32_arr, .bfloat16, s));
    return out;
}

fn kvAppendPrefill(cache: *KVCache, tokens: usize, seed: u32, s: mlx.mlx_stream) !void {
    const k = try kvAppendPacked(1, @intCast(tokens), seed, s);
    defer _ = mlx.mlx_array_free(k);
    const v = try kvAppendPacked(1, @intCast(tokens), seed ^ 0x9E3779B9, s);
    defer _ = mlx.mlx_array_free(v);
    var dv = try cache.update(0, k, v, s, 0);
    dv.deinit();
}

fn kvAppendOperandsEqual(a: *const KVCacheEntry, b: *const KVCacheEntry, s: mlx.mlx_stream) !void {
    try testing.expectEqual(a.offset, b.offset);
    try testing.expect(try arraysAllEqual(a.keys, b.keys, s));
    try testing.expect(try arraysAllEqual(a.values, b.values, s));
    try testing.expect(try arraysAllEqual(a.keys_scales, b.keys_scales, s));
    try testing.expect(try arraysAllEqual(a.keys_biases, b.keys_biases, s));
    try testing.expect(try arraysAllEqual(a.values_scales, b.values_scales, s));
    try testing.expect(try arraysAllEqual(a.values_biases, b.values_biases, s));
}

fn kvAppendDummyAttn(cache: *KVCache, s: mlx.mlx_stream) !mlx.mlx_array {
    var dv = try cache.denseView(0, s);
    defer dv.deinit();
    const ksh = mlx.getShape(dv.k);
    const q_shape = [_]c_int{ ksh[0], ksh[1], 1, ksh[3] };
    var q = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(q);
    try mlx.check(mlx.mlx_ones(&q, &q_shape, 4, .bfloat16, s));
    const none = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(none);
    var out = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(out);
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(kv_append_hd)));
    try mlx.check(mlx.mlx_fast_scaled_dot_product_attention(
        &out,
        q,
        dv.k,
        dv.v,
        scale,
        "",
        none,
        .{ .ctx = null },
        false,
        s,
    ));
    _ = mlx.mlx_array_free(q);
    return out;
}

test "batched KV append: affine-8 N=2/4/8 matches N solo updates at production geometry" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const alloc = testing.allocator;
    const s = mlx.gpuStream();
    const cfg = kv_quant.KVQuantConfig.affine(8);
    const ns = [_]usize{ 2, 4, 8 };
    const lens = [_]usize{ 2, 5, 3, 8, 4, 7, 6, 9 };
    for (ns) |n| {
        const solo = try alloc.alloc(KVCache, n);
        const batched = try alloc.alloc(KVCache, n);
        defer {
            for (solo) |*c| c.deinit();
            alloc.free(solo);
            for (batched) |*c| c.deinit();
            alloc.free(batched);
        }
        const solo_ptrs = try alloc.alloc(*KVCache, n);
        defer alloc.free(solo_ptrs);
        const batched_ptrs = try alloc.alloc(*KVCache, n);
        defer alloc.free(batched_ptrs);
        for (0..n) |i| {
            solo[i] = try KVCache.initWithConfig(alloc, 1, cfg);
            batched[i] = try KVCache.initWithConfig(alloc, 1, cfg);
            try kvAppendPrefill(&solo[i], lens[i], @intCast(0xA000 + i), s);
            try kvAppendPrefill(&batched[i], lens[i], @intCast(0xA000 + i), s);
            solo_ptrs[i] = &solo[i];
            batched_ptrs[i] = &batched[i];
        }
        const stacked_k = try kvAppendPacked(@intCast(n), 1, 0xC0FFE, s);
        defer _ = mlx.mlx_array_free(stacked_k);
        const stacked_v = try kvAppendPacked(@intCast(n), 1, 0x0D15EA, s);
        defer _ = mlx.mlx_array_free(stacked_v);
        try KVCache.appendFromStacked(stacked_k, stacked_v, solo_ptrs, 0, s, 0, false);
        try KVCache.appendFromStacked(stacked_k, stacked_v, batched_ptrs, 0, s, 0, true);
        for (0..n) |i| {
            try kvAppendOperandsEqual(&solo[i].entries[0], &batched[i].entries[0], s);
            const attn_s = try kvAppendDummyAttn(&solo[i], s);
            defer _ = mlx.mlx_array_free(attn_s);
            const attn_b = try kvAppendDummyAttn(&batched[i], s);
            defer _ = mlx.mlx_array_free(attn_b);
            try testing.expect(try arraysAllEqual(attn_s, attn_b, s));
        }
    }
}

test "batched KV append: two restored siblings append and truncate independently; the snapshot stays byte-identical" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const alloc = testing.allocator;
    const s = mlx.gpuStream();
    const cfg = kv_quant.KVQuantConfig.affine(8);
    var src = try KVCache.initWithConfig(alloc, 1, cfg);
    defer src.deinit();
    try kvAppendPrefill(&src, 6, 0x51A0, s);
    var snap = try src.snapshot();
    defer snap.deinit();
    const snap_k = try materializedOwnedCopy(s, snap.entries[0].keys);
    defer _ = mlx.mlx_array_free(snap_k);
    const snap_v = try materializedOwnedCopy(s, snap.entries[0].values);
    defer _ = mlx.mlx_array_free(snap_v);
    const snap_ks = try materializedOwnedCopy(s, snap.entries[0].keys_scales);
    defer _ = mlx.mlx_array_free(snap_ks);
    const snap_kb = try materializedOwnedCopy(s, snap.entries[0].keys_biases);
    defer _ = mlx.mlx_array_free(snap_kb);
    const snap_vs = try materializedOwnedCopy(s, snap.entries[0].values_scales);
    defer _ = mlx.mlx_array_free(snap_vs);
    const snap_vb = try materializedOwnedCopy(s, snap.entries[0].values_biases);
    defer _ = mlx.mlx_array_free(snap_vb);
    try mlx.check(mlx.mlx_array_eval(snap_k));
    var a = try KVCache.initWithConfig(alloc, 1, cfg);
    defer a.deinit();
    var b = try KVCache.initWithConfig(alloc, 1, cfg);
    defer b.deinit();
    try a.restore(&snap);
    try b.restore(&snap);
    const stacked_k = try kvAppendPacked(2, 1, 0xABBA, s);
    defer _ = mlx.mlx_array_free(stacked_k);
    const stacked_v = try kvAppendPacked(2, 1, 0xBEEF, s);
    defer _ = mlx.mlx_array_free(stacked_v);
    var sibs = [_]*KVCache{ &a, &b };
    try KVCache.appendBatched(stacked_k, stacked_v, &sibs, 0, s, 0, cfg);
    try testing.expectEqual(@as(usize, 7), a.entries[0].offset);
    try testing.expectEqual(@as(usize, 7), b.entries[0].offset);
    try a.truncate(6, s);
    try testing.expectEqual(@as(usize, 6), a.entries[0].offset);
    try testing.expectEqual(@as(usize, 7), b.entries[0].offset);
    try testing.expect(try arraysAllEqual(snap.entries[0].keys, snap_k, s));
    try testing.expect(try arraysAllEqual(snap.entries[0].values, snap_v, s));
    try testing.expect(try arraysAllEqual(snap.entries[0].keys_scales, snap_ks, s));
    try testing.expect(try arraysAllEqual(snap.entries[0].keys_biases, snap_kb, s));
    try testing.expect(try arraysAllEqual(snap.entries[0].values_scales, snap_vs, s));
    try testing.expect(try arraysAllEqual(snap.entries[0].values_biases, snap_vb, s));
    const k1 = try KVCache.sliceStackedRow(s, stacked_k, 0);
    defer _ = mlx.mlx_array_free(k1);
    const v1 = try KVCache.sliceStackedRow(s, stacked_v, 0);
    defer _ = mlx.mlx_array_free(v1);
    var dv = try a.update(0, k1, v1, s, 0);
    dv.deinit();
    try testing.expect(try arraysAllEqual(snap.entries[0].keys, snap_k, s));
}

test "batched KV append: per-layer op count is quantize-once plus per-slot writes, not N x (2 slices + update)" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const alloc = testing.allocator;
    const s = mlx.gpuStream();
    const cfg = kv_quant.KVQuantConfig.affine(8);
    const ns = [_]usize{ 2, 4, 8 };
    const lens = [_]usize{ 2, 5, 3, 8, 4, 7, 6, 9 };
    var solo_at: [3]u64 = undefined;
    var bat_at: [3]u64 = undefined;
    for (ns, 0..) |n, ni| {
        const solo = try alloc.alloc(KVCache, n);
        const batched = try alloc.alloc(KVCache, n);
        defer {
            for (solo) |*c| c.deinit();
            alloc.free(solo);
            for (batched) |*c| c.deinit();
            alloc.free(batched);
        }
        const solo_ptrs = try alloc.alloc(*KVCache, n);
        defer alloc.free(solo_ptrs);
        const batched_ptrs = try alloc.alloc(*KVCache, n);
        defer alloc.free(batched_ptrs);
        for (0..n) |i| {
            solo[i] = try KVCache.initWithConfig(alloc, 1, cfg);
            batched[i] = try KVCache.initWithConfig(alloc, 1, cfg);
            try kvAppendPrefill(&solo[i], lens[i], @intCast(0xB000 + i), s);
            try kvAppendPrefill(&batched[i], lens[i], @intCast(0xB000 + i), s);
            solo_ptrs[i] = &solo[i];
            batched_ptrs[i] = &batched[i];
        }
        const stacked_k = try kvAppendPacked(@intCast(n), 1, 0x1111, s);
        defer _ = mlx.mlx_array_free(stacked_k);
        const stacked_v = try kvAppendPacked(@intCast(n), 1, 0x2222, s);
        defer _ = mlx.mlx_array_free(stacked_v);
        const c_solo = mlx.op_count.load(.monotonic);
        try KVCache.appendFromStacked(stacked_k, stacked_v, solo_ptrs, 0, s, 0, false);
        solo_at[ni] = mlx.op_count.load(.monotonic) - c_solo;
        const c_bat = mlx.op_count.load(.monotonic);
        try KVCache.appendFromStacked(stacked_k, stacked_v, batched_ptrs, 0, s, 0, true);
        bat_at[ni] = mlx.op_count.load(.monotonic) - c_bat;
        std.debug.print("batched KV append op-count N={d}: solo {d} batched {d}\n", .{ n, solo_at[ni], bat_at[ni] });
        try testing.expectEqual(24 * @as(u64, @intCast(n)), solo_at[ni]);
        try testing.expectEqual(8 + 18 * @as(u64, @intCast(n)), bat_at[ni]);
    }
    try testing.expect((bat_at[2] - bat_at[0]) < (solo_at[2] - solo_at[0]));
}

test "batched KV append: dense and affine-4 stay on the per-slot path" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const alloc = testing.allocator;
    const s = mlx.gpuStream();
    const schemes = [_]kv_quant.KVQuantConfig{
        kv_quant.KVQuantConfig.dense,
        kv_quant.KVQuantConfig.affine(4),
    };
    for (schemes) |cfg| {
        var solo: [2]KVCache = .{ try KVCache.initWithConfig(alloc, 1, cfg), try KVCache.initWithConfig(alloc, 1, cfg) };
        var batched: [2]KVCache = .{ try KVCache.initWithConfig(alloc, 1, cfg), try KVCache.initWithConfig(alloc, 1, cfg) };
        defer for (&solo) |*c| c.deinit();
        defer for (&batched) |*c| c.deinit();
        try kvAppendPrefill(&solo[0], 3, 0x10, s);
        try kvAppendPrefill(&solo[1], 5, 0x11, s);
        try kvAppendPrefill(&batched[0], 3, 0x10, s);
        try kvAppendPrefill(&batched[1], 5, 0x11, s);
        var solo_ptrs = [_]*KVCache{ &solo[0], &solo[1] };
        var batched_ptrs = [_]*KVCache{ &batched[0], &batched[1] };
        const stacked_k = try kvAppendPacked(2, 1, 0x30, s);
        defer _ = mlx.mlx_array_free(stacked_k);
        const stacked_v = try kvAppendPacked(2, 1, 0x31, s);
        defer _ = mlx.mlx_array_free(stacked_v);
        const c0 = mlx.op_count.load(.monotonic);
        try KVCache.appendFromStacked(stacked_k, stacked_v, &solo_ptrs, 0, s, 0, false);
        const solo_ops = mlx.op_count.load(.monotonic) - c0;
        const c1 = mlx.op_count.load(.monotonic);
        try KVCache.appendFromStacked(stacked_k, stacked_v, &batched_ptrs, 0, s, 0, true);
        const batched_ops = mlx.op_count.load(.monotonic) - c1;
        try testing.expectEqual(solo_ops, batched_ops);
        for (0..2) |i| {
            try testing.expectEqual(solo[i].entries[0].offset, batched[i].entries[0].offset);
            try testing.expect(try arraysAllEqual(solo[i].entries[0].keys, batched[i].entries[0].keys, s));
            try testing.expect(try arraysAllEqual(solo[i].entries[0].values, batched[i].entries[0].values, s));
            if (cfg.scheme == .affine) {
                try kvAppendOperandsEqual(&solo[i].entries[0], &batched[i].entries[0], s);
            }
        }
    }
}

// Bar: the fused residual add + next norm is BIT-EQUAL to add -> fast rms_norm,
// on the plain arm and on the MoE-combine arm (with and without a shared expert).
test "add_norm: plain and MoE-combine arms match the composed ops" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const s = mlx.gpuStream();
    const R: c_int = 3;
    const D: c_int = 2688;
    const K: c_int = 3;
    const mk = struct {
        fn f(shape: []const c_int, seed: f32, dt: mlx.mlx_dtype, st: mlx.mlx_stream) !mlx.mlx_array {
            var n: usize = 1;
            for (shape) |d| n *= @intCast(d);
            var buf: [3 * 3 * 2688]f32 = undefined;
            for (buf[0..n], 0..) |*v, i| v.* = @sin(seed + 0.29 * @as(f32, @floatFromInt(i)));
            const src = mlx.mlx_array_new_data(&buf, shape.ptr, @intCast(shape.len), .float32);
            defer _ = mlx.mlx_array_free(src);
            var out = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_astype(&out, src, dt, st));
            return out;
        }
    }.f;
    const cmp = struct {
        fn f(a: mlx.mlx_array, b: mlx.mlx_array, st: mlx.mlx_stream, tol: f32) !void {
            var af = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(af);
            var bf = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(bf);
            try mlx.check(mlx.mlx_astype(&af, a, .float32, st));
            try mlx.check(mlx.mlx_astype(&bf, b, .float32, st));
            try mlx.check(mlx.mlx_array_eval(af));
            try mlx.check(mlx.mlx_array_eval(bf));
            const pa = mlx.mlx_array_data_float32(af) orelse return error.NoData;
            const pb = mlx.mlx_array_data_float32(bf) orelse return error.NoData;
            const n: usize = @intCast(mlx.mlx_array_size(af));
            var max_ref: f32 = 0;
            var max_err: f32 = 0;
            for (0..n) |i| {
                try std.testing.expect(std.math.isFinite(pa[i]) and std.math.isFinite(pb[i]));
                max_ref = @max(max_ref, @abs(pa[i]));
                max_err = @max(max_err, @abs(pa[i] - pb[i]));
            }
            if (!(max_ref > 0.01) or max_err > tol * max_ref) {
                std.debug.print("add_norm mismatch: max_err={d:.5} max_ref={d:.5}\n", .{ max_err, max_ref });
                return error.AddNormMismatch;
            }
        }
    }.f;
    const h = try mk(&.{ 1, R, D }, 0.1, .bfloat16, s);
    defer _ = mlx.mlx_array_free(h);
    const x = try mk(&.{ 1, R, D }, 0.7, .bfloat16, s);
    defer _ = mlx.mlx_array_free(x);
    const w = try mk(&.{D}, 1.3, .bfloat16, s);
    defer _ = mlx.mlx_array_free(w);
    const eps = mlx.mlx_array_new_float(1e-5);
    defer _ = mlx.mlx_array_free(eps);

    // Plain arm.
    {
        const got = (try add_norm.addNorm(h, x, w, eps, s)) orelse return error.Declined;
        defer _ = mlx.mlx_array_free(got.h);
        defer _ = mlx.mlx_array_free(got.normed);
        var sum = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(sum);
        try mlx.check(mlx.mlx_add(&sum, h, x, s));
        var normed = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(normed);
        try mlx.check(mlx.mlx_fast_rms_norm(&normed, sum, w, 1e-5, s));
        try cmp(sum, got.h, s, 0);
        try cmp(normed, got.normed, s, 0);
    }
    // MoE-combine arm: f32 weighted sum over K slots, then the shared expert
    // (and once without one).
    for ([_]bool{ true, false }) |with_shared| {
        const y = try mk(&.{ R, K, D }, 2.1, .bfloat16, s);
        defer _ = mlx.mlx_array_free(y);
        const wt = try mk(&.{ R, K }, 0.4, .float32, s);
        defer _ = mlx.mlx_array_free(wt);
        const xs = try mk(&.{ R, D }, 1.9, .bfloat16, s);
        defer _ = mlx.mlx_array_free(xs);
        const got = (try add_norm.moeCombineAddNorm(h, y, wt, if (with_shared) xs else null, w, eps, s)) orelse return error.Declined;
        defer _ = mlx.mlx_array_free(got.h);
        defer _ = mlx.mlx_array_free(got.normed);
        var wt_e = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wt_e);
        try mlx.check(mlx.mlx_expand_dims(&wt_e, wt, -1, s));
        var prod = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(prod);
        try mlx.check(mlx.mlx_multiply(&prod, y, wt_e, s));
        var summed = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(summed);
        try mlx.check(mlx.mlx_sum_axis(&summed, prod, 1, false, s));
        var routed = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(routed);
        try mlx.check(mlx.mlx_astype(&routed, summed, .bfloat16, s));
        var delta = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(delta);
        if (with_shared) try mlx.check(mlx.mlx_add(&delta, routed, xs, s)) else try mlx.check(mlx.mlx_array_set(&delta, routed));
        var delta3 = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(delta3);
        try mlx.check(mlx.mlx_reshape(&delta3, delta, &[_]c_int{ 1, R, D }, 3, s));
        var sum = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(sum);
        try mlx.check(mlx.mlx_add(&sum, h, delta3, s));
        var normed = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(normed);
        try mlx.check(mlx.mlx_fast_rms_norm(&normed, sum, w, 1e-5, s));
        try cmp(sum, got.h, s, 0);
        try cmp(normed, got.normed, s, 0);
    }
}

// Bar: the default is off; a flag turns it on, a model setting beats both.
test "lm_head mxfp8: off by default, settings and flags win" {
    const t = std.testing;
    try t.expect(!lmHeadMxfp8On(null, null));
    try t.expect(!lmHeadMxfp8On(null, false));
    try t.expect(lmHeadMxfp8On(null, true));
