// Bar: vLLM's MXFP8 bytes (scale 2^ceil(log2(amax/448)), e4m3 nearest-even), the map holds them in place of the bf16 head, logits within 5% RMS.
test "lm_head mxfp8: a dense head loads as vLLM's MXFP8 bytes in place of the bf16 copy" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const t = std.testing;
    const allocator = t.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    const s = mlx.gpuStream();
    const Fix = @import("dflash.zig").TinyFix;
    const V = Fix.VOCAB;
    const H = Fix.HIDDEN;
    const E4m3 = struct {
        fn nearestEven(x: f32) f32 {
            const a = @abs(x);
            if (a == 0) return 0;
            const step = std.math.exp2(@max(@floor(std.math.log2(a)), -6) - 3);
            const r = @floor(a / step);
            const up = a / step - r > 0.5 or (a / step - r == 0.5 and @mod(r, 2) == 1);
            return std.math.copysign((if (up) r + 1 else r) * step, x);
        }
    };
    var tmp = t.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [512]u8 = undefined;
    const dir = path_buf[0..try tmp.dir.realPath(io, &path_buf)];
    try Fix.writeTrunk(io, tmp.dir, dir, s);
    const ids = mlx.mlx_array_new_data(&[_]i32{ 1, 4, 7 }, &[_]c_int{ 1, 3 }, 2, .int32);
    defer _ = mlx.mlx_array_free(ids);
    var logits: [2][]f32 = .{ &.{}, &.{} };
    defer for (logits) |l| allocator.free(l);
    for ([_]bool{ false, true }, &logits) |mxfp8, *out| {
        var config = try model_mod.parseConfig(io, allocator, dir);
        defer config.deinit(allocator);
        config.tie_word_embeddings = false;
        config.lm_head_mxfp8_override = mxfp8;
        var weights = try model_mod.loadWeights(io, allocator, dir);
        defer weights.deinit();
        model_mod.resolveWeightPrefix(&config, &weights);
        try weights.put("lm_head.weight", try Fix.bf16Arr(V, H, 99, s));
        var xfm = try Transformer.init(io, allocator, config, &weights);
        defer xfm.deinit();
        const head = weights.get("lm_head.weight").?;
        try t.expectEqual(head.ctx, xfm.lm_head_w.ctx);
        try t.expectEqual(mxfp8, xfm.lm_head_s.ctx != null);
        if (mxfp8) {
            try t.expect(mlx.mlx_array_dtype(xfm.lm_head_s) == .uint8);
            try t.expectEqualSlices(c_int, &.{ V, H / 32 }, mlx.getShape(xfm.lm_head_s));
            try t.expectEqual(xfm.lm_head_s.ctx, weights.get("lm_head.scales").?.ctx);
            const ref = try Fix.bf16Arr(V, H, 99, s);
            defer _ = mlx.mlx_array_free(ref);
            const w = try Fix.readF32(ref, allocator, s);
            defer allocator.free(w);
            var deq = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(deq);
            try mlx.check(mlx.mlx_dequantize(&deq, head, xfm.lm_head_s, .{ .ctx = null }, mlx.mlx_optional_int.some(32), mlx.mlx_optional_int.some(8), "mxfp8", .{ .ctx = null }, .{ .value = .float32, .has_value = true }, s));
            const got = try Fix.readF32(deq, allocator, s);
            defer allocator.free(got);
            try mlx.check(mlx.mlx_array_eval(xfm.lm_head_s));
            const bytes = mlx.mlx_array_data_uint8(xfm.lm_head_s).?;
            for (0..V * H / 32) |g| {
                var amax: f32 = 0;
                for (w[g * 32 ..][0..32]) |x| amax = @max(amax, @abs(x));
                const e = @ceil(std.math.log2(amax / 448.0));
                try t.expectEqual(@as(u8, @intFromFloat(e + 127)), bytes[g]);
                for (w[g * 32 ..][0..32], got[g * 32 ..][0..32]) |x, y|
                    try t.expectEqual(E4m3.nearestEven(x / std.math.exp2(e)) * std.math.exp2(e), y);
            }
        }
        const l = try xfm.forward(ids);
        defer _ = mlx.mlx_array_free(l);
        out.* = try Fix.readF32(l, allocator, s);
    }
    var err: f64 = 0;
    var ref: f64 = 0;
    for (logits[0], logits[1]) |a, b| {
        err += (b - a) * (b - a);
        ref += a * a;
    }
    try t.expect(err > 0 and @sqrt(err / ref) < 0.05);
}

test "affineParamsFromGeometry: exact per-weight solve for off-config sidecar quants" {
    // Real geometries from the stamsam 35B-A3B draft sidecars over a 4-bit/gs-64
    // affine trunk: q_proj 5-bit/gs-128, v_proj 6-bit/gs-128, shared expert
    // 8-bit/gs-128, switch experts 4-bit/gs-64. The old config-gs detection
    // (detectQuantBits with gs 64) returns garbage for the gs-128 tensors.
    const s = mlx.gpuStream();
    const H = 2048; // sidecar hidden

    const mk = struct {
        fn arr(shape: []const c_int, dt: mlx.mlx_dtype, st: mlx.mlx_stream) !mlx.mlx_array {
            var a = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_zeros(&a, shape.ptr, shape.len, dt, st));
            return a;
        }
    };

    // q_proj: w [8192, 320] u32, scales [8192, 16] bf16 → 5-bit / gs 128.
    const wq = try mk.arr(&.{ 8192, 320 }, .uint32, s);
    defer _ = mlx.mlx_array_free(wq);
    const sq = try mk.arr(&.{ 8192, 16 }, .bfloat16, s);
    defer _ = mlx.mlx_array_free(sq);
    const qp_q = affineParamsFromGeometry(wq, sq, H) orelse return error.TestUnexpectedResult;
    try testing.expectEqual(@as(u32, 5), qp_q.bits);
    try testing.expectEqual(@as(u32, 128), qp_q.group_size);

    // v_proj: w [512, 384] u32, scales [512, 16] bf16 → 6-bit / gs 128.
    const wv = try mk.arr(&.{ 512, 384 }, .uint32, s);
    defer _ = mlx.mlx_array_free(wv);
    const sv = try mk.arr(&.{ 512, 16 }, .bfloat16, s);
    defer _ = mlx.mlx_array_free(sv);
    const qp_v = affineParamsFromGeometry(wv, sv, H) orelse return error.TestUnexpectedResult;
    try testing.expectEqual(@as(u32, 6), qp_v.bits);
    try testing.expectEqual(@as(u32, 128), qp_v.group_size);

    // Switch experts (3D): w [256, 512, 256] u32, scales [256, 512, 32] bf16
    // → 4-bit / gs 64 (trunk-standard - must still solve).
    const we = try mk.arr(&.{ 256, 512, 256 }, .uint32, s);
    defer _ = mlx.mlx_array_free(we);
    const se = try mk.arr(&.{ 256, 512, 32 }, .bfloat16, s);
    defer _ = mlx.mlx_array_free(se);
    const qp_e = affineParamsFromGeometry(we, se, H) orelse return error.TestUnexpectedResult;
    try testing.expectEqual(@as(u32, 4), qp_e.bits);
    try testing.expectEqual(@as(u32, 64), qp_e.group_size);

    // Degenerate: bits wouldn't divide exactly → null (caller falls back).
    const qp_bad = affineParamsFromGeometry(wq, sq, 3000);
    try testing.expect(qp_bad == null);

    // And through computeQuantParams on an AFFINE gs-64 config: the hinted
    // exact solve must WIN over the config group size (pre-fix this returned
    // bits 10 / gs 64 for the q_proj geometry).
    var cfg = ModelConfig{};
    cfg.quant_bits = 4;
    cfg.quant_group_size = 64;
    cfg.quant_mode = .affine;
    const qp_via = computeQuantParams(&cfg, wq, sq, H);
    try testing.expectEqual(@as(u32, 5), qp_via.bits);
    try testing.expectEqual(@as(u32, 128), qp_via.group_size);
}

test "computeQuantParams resolves an fp override INSIDE the fp family (mxfp8 embed under mxfp4)" {
    // A pack declaring a model-wide mxfp4/gs32 AND a
    // per-tensor override: `"model.embed_tokens": {bits 8, group_size 32,
    // mode "mxfp8"}`. Both modes carry uint8 (E8M0) scales, so the
    // scales-dtype rule cannot tell them apart and the embedding resolved at
    // the model-wide 4 bits - `mlx_dequantize` then rejected the shapes
    // ("matrix of shape (1,512) and scales of shape (1,64)"), and an MLX error
    // is not a Zig error: the first request killed the server.
    //
    // The packed geometry states the answer exactly, the same way the affine
    // path already solves off-config sidecar quants.
    const s = mlx.gpuStream();
    const H = 2048; // hidden size

    const mk = struct {
        fn arr(shape: []const c_int, dt: mlx.mlx_dtype, st: mlx.mlx_stream) !mlx.mlx_array {
            var a = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_zeros(&a, shape.ptr, shape.len, dt, st));
            return a;
        }
    };

    var cfg = ModelConfig{};
    cfg.quant_bits = 4;
    cfg.quant_group_size = 32;
    cfg.quant_mode = .mxfp4;

    // embed_tokens: w [V, 512] u32 + scales [V, 64] u8 → 2048 values/row at
    // 8 bits, gs 32. (Real shapes; V shrunk - only the last axis is read.)
    const we = try mk.arr(&.{ 1024, 512 }, .uint32, s);
    defer _ = mlx.mlx_array_free(we);
    const se = try mk.arr(&.{ 1024, 64 }, .uint8, s);
    defer _ = mlx.mlx_array_free(se);
    const qp_e = computeQuantParams(&cfg, we, se, H);
    try testing.expectEqual(QuantMode.mxfp8, qp_e.mode);
    try testing.expectEqual(@as(u32, 8), qp_e.bits);
    try testing.expectEqual(@as(u32, 32), qp_e.group_size);

    // An ordinary mxfp4 linear in the SAME model: w [2048, 256] + [2048, 64].
    // Unchanged - the config already describes it.
    const wl = try mk.arr(&.{ 2048, 256 }, .uint32, s);
    defer _ = mlx.mlx_array_free(wl);
    const sl = try mk.arr(&.{ 2048, 64 }, .uint8, s);
    defer _ = mlx.mlx_array_free(sl);
    const qp_l = computeQuantParams(&cfg, wl, sl, H);
    try testing.expectEqual(QuantMode.mxfp4, qp_l.mode);
    try testing.expectEqual(@as(u32, 4), qp_l.bits);
    try testing.expectEqual(@as(u32, 32), qp_l.group_size);

    // An nvfp4 model's own tensors (gs 16) stay nvfp4 - the solve agrees with
    // the config, so it never re-labels a consistent checkpoint.
    var cfg_nv = ModelConfig{};
    cfg_nv.quant_bits = 4;
    cfg_nv.quant_group_size = 16;
    cfg_nv.quant_mode = .nvfp4;
    const s_nv = try mk.arr(&.{ 2048, 128 }, .uint8, s);
    defer _ = mlx.mlx_array_free(s_nv);
    const qp_nv = computeQuantParams(&cfg_nv, wl, s_nv, H);
    try testing.expectEqual(QuantMode.nvfp4, qp_nv.mode);
    try testing.expectEqual(@as(u32, 16), qp_nv.group_size);

    // A geometry that maps to no fp format we serve is NOT invented into one:
    // the config stands, and the load fails honestly if it really disagrees.
    const s_odd = try mk.arr(&.{ 2048, 21 }, .uint8, s);
    defer _ = mlx.mlx_array_free(s_odd);
    const qp_odd = computeQuantParams(&cfg, wl, s_odd, H);
    try testing.expectEqual(QuantMode.mxfp4, qp_odd.mode);
    try testing.expectEqual(@as(u32, 4), qp_odd.bits);
    try testing.expectEqual(@as(u32, 32), qp_odd.group_size);

    // No inner-dim hint: bits x group_size (256 / 128 / 64) still names one fp format.
    const qp_nohint = computeQuantParams(&cfg, we, se, null);
    try testing.expectEqual(QuantMode.mxfp8, qp_nohint.mode);
    try testing.expectEqual(@as(u32, 8), qp_nohint.bits);
    const qp_nohint_nv = computeQuantParams(&cfg, wl, s_nv, null);
    try testing.expectEqual(QuantMode.nvfp4, qp_nohint_nv.mode);
    try testing.expectEqual(@as(u32, 16), qp_nohint_nv.group_size);
    const qp_nohint_odd = computeQuantParams(&cfg, wl, s_odd, null);
    try testing.expectEqual(QuantMode.mxfp4, qp_nohint_odd.mode);
}

test "computeQuantParams resolves mixed nvfp4 + affine-override weights" {
    // Real-world shape: gemma-4 QAT nvfp4 checkpoints quantize most tensors
    // nvfp4 (uint8 fp8 scales, gs 16) but override the shared MLP to affine
    // 8-bit/gs64 (bf16 scales + biases). Detection key: scales dtype, then
    // the activation inner dim to pin (bits, group_size) for the override.
    const s = mlx.gpuStream();
    const IN = 2560;
    const OUT = 8;

    var cfg = ModelConfig{};
    cfg.quant_bits = 4;
    cfg.quant_group_size = 16;
    cfg.quant_mode = .nvfp4;

    // nvfp4 tensor: w [OUT, IN*4/32] u32, scales [OUT, IN/16] u8.
    var w_nv = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(w_nv);
    var sc_nv = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(sc_nv);
    const w_nv_sh = [_]c_int{ OUT, IN * 4 / 32 };
    const sc_nv_sh = [_]c_int{ OUT, IN / 16 };
    try mlx.check(mlx.mlx_zeros(&w_nv, &w_nv_sh, 2, .uint32, s));
    try mlx.check(mlx.mlx_zeros(&sc_nv, &sc_nv_sh, 2, .uint8, s));
    const qp_nv = computeQuantParams(&cfg, w_nv, sc_nv, null);
    try testing.expectEqual(QuantMode.nvfp4, qp_nv.mode);
    try testing.expectEqual(@as(u32, 4), qp_nv.bits);
    try testing.expectEqual(@as(u32, 16), qp_nv.group_size);

    // Affine 8-bit/gs64 override: w [OUT, IN*8/32] u32, scales [OUT, IN/64] bf16.
    var w_af = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(w_af);
    var sc_af = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(sc_af);
    const w_af_sh = [_]c_int{ OUT, IN * 8 / 32 };
    const sc_af_sh = [_]c_int{ OUT, IN / 64 };
    try mlx.check(mlx.mlx_zeros(&w_af, &w_af_sh, 2, .uint32, s));
    try mlx.check(mlx.mlx_zeros(&sc_af, &sc_af_sh, 2, .bfloat16, s));

    // With the activation inner-dim hint: exact.
    const qp_af = computeQuantParams(&cfg, w_af, sc_af, IN);
    try testing.expectEqual(QuantMode.affine, qp_af.mode);
    try testing.expectEqual(@as(u32, 8), qp_af.bits);
    try testing.expectEqual(@as(u32, 64), qp_af.group_size);

    // Without a hint: falls back to mlx-lm's override default gs=64.
    const qp_af_nohint = computeQuantParams(&cfg, w_af, sc_af, null);
    try testing.expectEqual(QuantMode.affine, qp_af_nohint.mode);
    try testing.expectEqual(@as(u32, 8), qp_af_nohint.bits);
    try testing.expectEqual(@as(u32, 64), qp_af_nohint.group_size);

    // Plain affine model (config mode affine, bf16 scales): unchanged
    // detect-against-config-gs behavior.
    var cfg_affine = ModelConfig{};
    cfg_affine.quant_bits = 4;
    cfg_affine.quant_group_size = 64;
    cfg_affine.quant_mode = .affine;
    const qp_plain = computeQuantParams(&cfg_affine, w_af, sc_af, null);
    try testing.expectEqual(QuantMode.affine, qp_plain.mode);
    try testing.expectEqual(@as(u32, 8), qp_plain.bits);
    try testing.expectEqual(@as(u32, 64), qp_plain.group_size);
}

test "QuantParamsCache put/lookup round-trip" {
    var cache: BitsCache = .{};
    const s = mlx.gpuStream();

    // Three real arrays with distinct ctx pointers - the cache keys.
    var a = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(a);
    var b = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(b);
    var c = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(c);
    const shape = [_]c_int{8};
    try mlx.check(mlx.mlx_zeros(&a, &shape, 1, .bfloat16, s));
    try mlx.check(mlx.mlx_zeros(&b, &shape, 1, .bfloat16, s));
    try mlx.check(mlx.mlx_zeros(&c, &shape, 1, .bfloat16, s));

    try testing.expect(cache.put(a.ctx.?, .{ .bits = 4, .group_size = 32, .mode = .affine }));
    try testing.expect(cache.put(b.ctx.?, .{ .bits = 4, .group_size = 64, .mode = .nvfp4 }));
    try testing.expect(cache.put(c.ctx.?, .{ .bits = 8, .group_size = 128, .mode = .affine }));

    // Build a Transformer-like view over the cache via quantParamsFor - we
    // need a real Transformer to call the method, so verify by direct slot
    // lookup instead. (The forward path goes through quantParamsFor, which is
    // exercised by integration tests; this test pins the data structure.)
    {
        const idx = BitsCache.slot(a.ctx.?);
        var found = false;
        for (0..4) |i| {
            const j = (idx + i) & (BITS_CACHE_CAP - 1);
            if (cache.keys[j] == a.ctx) {
                try testing.expectEqual(@as(u8, 4), cache.vals_bits[j]);
                try testing.expectEqual(@as(u8, 32 / 8), cache.vals_gs_div8[j]);
                try testing.expectEqual(@backingInt(QuantMode.affine), cache.vals_mode[j]);
                found = true;
                break;
            }
        }
        try testing.expect(found);
    }
    {
        const idx = BitsCache.slot(c.ctx.?);
        var found = false;
        for (0..4) |i| {
            const j = (idx + i) & (BITS_CACHE_CAP - 1);
            if (cache.keys[j] == c.ctx) {
                try testing.expectEqual(@as(u8, 8), cache.vals_bits[j]);
                try testing.expectEqual(@as(u8, 128 / 8), cache.vals_gs_div8[j]);
                try testing.expectEqual(@backingInt(QuantMode.affine), cache.vals_mode[j]);
                found = true;
                break;
            }
        }
        try testing.expect(found);
    }
}

test "qmatmulBits dispatches to plain matmul when scales has null ctx (Unsloth Dynamic bf16)" {
    const s = mlx.gpuStream();

    // x: [1, 1, in=4], w: [out=2, in=4] (PyTorch convention).
    // Expected: x @ w.T = [1, 1, 2]
    var x_flat = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(x_flat);
    try mlx.check(mlx.mlx_arange(&x_flat, 0.0, 4.0, 1.0, .float32, s));
    var x = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(x);
    {
        const sh = [_]c_int{ 1, 1, 4 };
        try mlx.check(mlx.mlx_reshape(&x, x_flat, &sh, 3, s));
    }

    var w_flat = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(w_flat);
    try mlx.check(mlx.mlx_arange(&w_flat, 0.0, 8.0, 1.0, .float32, s));
    var w = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(w);
    {
        const sh = [_]c_int{ 2, 4 };
        try mlx.check(mlx.mlx_reshape(&w, w_flat, &sh, 2, s));
    }

    // Pre-transpose like initMoeLayers does for null-scales weights: [out, in] → [in, out]
    const w_t = try transposeBf16Weight(w, s);
    defer _ = mlx.mlx_array_free(w_t);

    // qmatmulBits with null sc/bi must plain-matmul x @ w_t.
    const null_sc = mlx.mlx_array{ .ctx = null };
    const null_bi = mlx.mlx_array{ .ctx = null };
    const got = try qmatmulBits(x, w_t, null_sc, null_bi, 4, 64, .affine, s);
    defer _ = mlx.mlx_array_free(got);

    // Reduce to host floats for comparison.
    var got_f32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(got_f32);
    try mlx.check(mlx.mlx_astype(&got_f32, got, .float32, s));
    var got_flat = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(got_flat);
    {
        const sh = [_]c_int{2};
        try mlx.check(mlx.mlx_reshape(&got_flat, got_f32, &sh, 1, s));
    }
    {
        const ev = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(ev);
        _ = mlx.mlx_vector_array_append_value(ev, got_flat);
        try mlx.check(mlx.mlx_eval(ev));
    }
    const data = mlx.mlx_array_data_float32(got_flat) orelse return error.TestUnexpectedNullData;
    // [0,1,2,3] @ [[0,4],[1,5],[2,6],[3,7]] = [0+1*1+2*2+3*3, 0+1*5+2*6+3*7] = [14, 38]
    // (w transposed from [[0,1,2,3],[4,5,6,7]] gives w_t = [[0,4],[1,5],[2,6],[3,7]])
    try testing.expectApproxEqAbs(@as(f32, 14.0), data[0], 1e-3);
    try testing.expectApproxEqAbs(@as(f32, 38.0), data[1], 1e-3);
}

/// Test helper: eval `arr`, flatten, and copy the first `out.len` f32 values to host.
fn testReadF32(arr: mlx.mlx_array, out: []f32, s: mlx.mlx_stream) !void {
    var f = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(f);
    try mlx.check(mlx.mlx_astype(&f, arr, .float32, s));
    var flat = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(flat);
    const sh = [_]c_int{@intCast(out.len)};
    try mlx.check(mlx.mlx_reshape(&flat, f, &sh, 1, s));
    const ev = mlx.mlx_vector_array_new();
    defer _ = mlx.mlx_vector_array_free(ev);
    _ = mlx.mlx_vector_array_append_value(ev, flat);
    try mlx.check(mlx.mlx_eval(ev));
    const data = mlx.mlx_array_data_float32(flat) orelse return error.TestUnexpectedNullData;
    @memcpy(out, data[0..out.len]);
}

/// Host-side reference for one router row: exact top-K by key with the
/// LOWEST-INDEX tie-break, weights in f64. Returns the selected ids in
/// descending-key order, matching the kernel's emission order.
fn routerRefRow(keys: []const f64, k: usize, out_ids: []usize) void {
    var taken = std.testing.allocator.alloc(bool, keys.len) catch unreachable;
    defer std.testing.allocator.free(taken);
    @memset(taken, false);
    for (0..k) |r| {
        var best: f64 = -std.math.inf(f64);
        var bidx: usize = 0;
        var found = false;
        for (keys, 0..) |v, i| {
            if (taken[i]) continue;
            if (!found or v > best) {
                best = v;
                bidx = i;
                found = true;
            }
        }
        taken[bidx] = true;
        out_ids[r] = bidx;
    }
}

test "fused MoE router reproduces the softmax routing chain's top-K and beats its weights" {
    // Selection is discrete: a different expert set is a different model, so
    // the ids are asserted EXACTLY against an fp64 host reference. The weights
    // follow the kernel rule - no worse than the fp64 reference, never
    // kernel-vs-kernel equality (the chain rounds a full bf16 softmax; the
    // kernel rounds once).
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0xC0FFEE11);
    const rnd = prng.random();
    moe_router_fused_override = true;
    defer moe_router_fused_override = null;

    const ROWS: c_int = 5;
    const E: c_int = 256;
    const K: c_int = 8;
    const n: usize = @intCast(ROWS * E);

    const buf = try allocator.alloc(f32, n);
    defer allocator.free(buf);
    // Spread wide enough that a bf16 round-trip leaves the top-K boundary
    // unambiguous; ties there would make "the chain's set" undefined, not wrong.
    for (buf, 0..) |*v, i| v.* = (rnd.float(f32) - 0.5) * 8.0 + @as(f32, @floatFromInt(i % 7)) * 0.011;
    const lsh = [_]c_int{ ROWS, E };
    const l32 = mlx.mlx_array_new_data(buf.ptr, &lsh, 2, .float32);
    defer _ = mlx.mlx_array_free(l32);
    var lbf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(lbf);
    try mlx.check(mlx.mlx_astype(&lbf, l32, .bfloat16, s));

    // The kernel and the reference must see the SAME bf16 values.
    const host = try allocator.alloc(f32, n);
    defer allocator.free(host);
    try testReadF32(lbf, host, s);

    const fused = (try moeRouterTopK(s, lbf, .{ .ctx = null }, K, .softmax, true, 1.0, .bfloat16, 0, 0, null)) orelse
        return error.FusedRouterDeclined;
    defer _ = mlx.mlx_array_free(fused.inds);
    defer _ = mlx.mlx_array_free(fused.norm_scores);
    const chain = try moeRoutingChain(lbf, K, s);
    defer _ = mlx.mlx_array_free(chain.inds);
    defer _ = mlx.mlx_array_free(chain.norm_scores);

    const kn: usize = @intCast(ROWS * K);
    const f_ids = try allocator.alloc(f32, kn);
    defer allocator.free(f_ids);
    const c_ids = try allocator.alloc(f32, kn);
    defer allocator.free(c_ids);
    const f_w = try allocator.alloc(f32, kn);
    defer allocator.free(f_w);
    const c_w = try allocator.alloc(f32, kn);
    defer allocator.free(c_w);
    try testReadF32(fused.inds, f_ids, s);
    try testReadF32(chain.inds, c_ids, s);
    try testReadF32(fused.norm_scores, f_w, s);
    try testReadF32(chain.norm_scores, c_w, s);

    const keys = try allocator.alloc(f64, @intCast(E));
    defer allocator.free(keys);
    var ref_ids: [8]usize = undefined;
    var fused_err: f64 = 0;
    var chain_err: f64 = 0;
    for (0..@intCast(ROWS)) |r| {
        const row = host[r * @as(usize, @intCast(E)) ..][0..@intCast(E)];
        for (row, 0..) |v, i| keys[i] = @floatCast(v);
        routerRefRow(keys, @intCast(K), &ref_ids);

        // Exact ids, in the kernel's descending-key order.
        for (0..@intCast(K)) |j| {
            try testing.expectEqual(ref_ids[j], @as(usize, @intFromFloat(f_ids[r * @as(usize, @intCast(K)) + j])));
        }
        // The chain's order is argpartition's, so compare it as a SET.
        var chain_set: [8]usize = undefined;
        for (0..@intCast(K)) |j| chain_set[j] = @intFromFloat(c_ids[r * @as(usize, @intCast(K)) + j]);
        std.mem.sort(usize, &chain_set, {}, std.sort.asc(usize));
        var ref_sorted = ref_ids;
        std.mem.sort(usize, &ref_sorted, {}, std.sort.asc(usize));
        try testing.expectEqualSlices(usize, &ref_sorted, &chain_set);

        // fp64 reference weights: softmax over the selected logits.
        var denom: f64 = 0;
        var num: [8]f64 = undefined;
        for (0..@intCast(K)) |j| {
            num[j] = @exp(keys[ref_ids[j]] - keys[ref_ids[0]]);
            denom += num[j];
        }
        for (0..@intCast(K)) |j| {
            const want = num[j] / denom;
            const got = f_w[r * @as(usize, @intCast(K)) + j];
            fused_err = @max(fused_err, @abs(want - @as(f64, got)));
            // Chain rows are in argpartition order - find this id's slot.
            var slot: usize = 0;
            while (slot < @as(usize, @intCast(K))) : (slot += 1) {
                if (@as(usize, @intFromFloat(c_ids[r * @as(usize, @intCast(K)) + slot])) == ref_ids[j]) break;
            }
            const chain_got = c_w[r * @as(usize, @intCast(K)) + slot];
            chain_err = @max(chain_err, @abs(want - @as(f64, chain_got)));
            // BIT equality with the chain: the kernel replicates the chain's
            // arithmetic, and anything else is a different model (a live A/B on
            // gemma4-26B-A4B diverged at token ~80 when it did not).
            try testing.expectEqual(chain_got, got);
        }
    }
    try testing.expect(fused_err <= chain_err);
}

test "fused softmax router folds the shared-expert gate's logit: routing unchanged, the logit within a bf16 ulp of the f64 dot" {
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x6A7E10);
    const rnd = prng.random();
    moe_router_fused_override = true;
    defer moe_router_fused_override = null;

    const rows: c_int = 3;
    const E: c_int = 512;
    const K: c_int = 10;
    const GK: c_int = 2560;
    const randBf = struct {
        fn f(a: std.mem.Allocator, r: std.Random, st: mlx.mlx_stream, shape: []const c_int, scale: f32) !mlx.mlx_array {
            var n: usize = 1;
            for (shape) |d| n *= @intCast(d);
            const buf = try a.alloc(f32, n);
            defer a.free(buf);
            for (buf) |*v| v.* = (r.float(f32) - 0.5) * scale;
            const a32 = mlx.mlx_array_new_data(buf.ptr, shape.ptr, @intCast(shape.len), .float32);
            defer _ = mlx.mlx_array_free(a32);
            var out = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_astype(&out, a32, .bfloat16, st));
            return out;
        }
    }.f;
    const logits = try randBf(allocator, rnd, s, &.{ rows, E }, 8.0);
    defer _ = mlx.mlx_array_free(logits);
    const x = try randBf(allocator, rnd, s, &.{ rows, GK }, 4.0);
    defer _ = mlx.mlx_array_free(x);
    const w = try randBf(allocator, rnd, s, &.{GK}, 0.4);
    defer _ = mlx.mlx_array_free(w);

    const plain = (try moeRouterTopK(s, logits, .{ .ctx = null }, K, .softmax, true, 1.0, .bfloat16, 0, 0, null)) orelse return error.FusedRouterDeclined;
    defer _ = mlx.mlx_array_free(plain.inds);
    defer _ = mlx.mlx_array_free(plain.norm_scores);
    const gated = (try moeRouterTopK(s, logits, .{ .ctx = null }, K, .softmax, true, 1.0, .bfloat16, 0, 0, .{ .x = x, .w = w })) orelse return error.FusedRouterDeclined;
    defer _ = mlx.mlx_array_free(gated.inds);
    defer _ = mlx.mlx_array_free(gated.norm_scores);
    defer _ = mlx.mlx_array_free(gated.gate_logit);
    try testing.expect(gated.gate_logit.ctx != null);

    const kn: usize = @intCast(rows * K);
    inline for (.{ "inds", "norm_scores" }) |name| {
        const a = try allocator.alloc(f32, kn);
        defer allocator.free(a);
        const b = try allocator.alloc(f32, kn);
        defer allocator.free(b);
        try testReadF32(@field(plain, name), a, s);
        try testReadF32(@field(gated, name), b, s);
        try testing.expectEqualSlices(f32, a, b);
    }

    const xn: usize = @intCast(rows * GK);
    const xh = try allocator.alloc(f32, xn);
    defer allocator.free(xh);
    const wh = try allocator.alloc(f32, @intCast(GK));
    defer allocator.free(wh);
    const got = try allocator.alloc(f32, @intCast(rows));
    defer allocator.free(got);
    try testReadF32(x, xh, s);
    try testReadF32(w, wh, s);
    try testReadF32(gated.gate_logit, got, s);
    for (0..@intCast(rows)) |r| {
        var want: f64 = 0;
        for (wh, 0..) |wv, k| want += @as(f64, wv) * xh[r * @as(usize, @intCast(GK)) + k];
        try testing.expect(@abs(@as(f64, got[r]) - want) <= 0.004 * @abs(want) + 1e-3);
    }
}

test "fused softmax router: a router with no spare simdgroup routes without the gate logit" {
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0x6A7E11);
    const rnd = prng.random();
    moe_router_fused_override = true;
    defer moe_router_fused_override = null;

    // 16 experts is one simdgroup: nothing is left to dot the gate vector, and a zero logit must never ship.
    const logits = try testRandUniformBf16(rnd, &.{ 2, 16 }, -4.0, 4.0, s);
    defer _ = mlx.mlx_array_free(logits);
    const x = try testRandUniformBf16(rnd, &.{ 2, 64 }, -2.0, 2.0, s);
    defer _ = mlx.mlx_array_free(x);
    const w = try testRandUniformBf16(rnd, &.{64}, -0.2, 0.2, s);
    defer _ = mlx.mlx_array_free(w);

    const plain = (try moeRouterTopK(s, logits, .{ .ctx = null }, 4, .softmax, true, 1.0, .bfloat16, 0, 0, null)) orelse return error.FusedRouterDeclined;
    defer _ = mlx.mlx_array_free(plain.inds);
    defer _ = mlx.mlx_array_free(plain.norm_scores);
    const gated = (try moeRouterTopK(s, logits, .{ .ctx = null }, 4, .softmax, true, 1.0, .bfloat16, 0, 0, .{ .x = x, .w = w })) orelse return error.FusedRouterDeclined;
    defer _ = mlx.mlx_array_free(gated.inds);
    defer _ = mlx.mlx_array_free(gated.norm_scores);
    try testing.expect(gated.gate_logit.ctx == null);
    inline for (.{ "inds", "norm_scores" }) |name| {
        var a: [8]f32 = undefined;
        var b: [8]f32 = undefined;
        try testReadF32(@field(plain, name), &a, s);
        try testReadF32(@field(gated, name), &b, s);
        try testing.expectEqualSlices(f32, &a, &b);
    }
}

test "fused attention output gate is bit-identical to the softplus op chain" {
    if (!mlx.metalKernelsAvailable()) return error.SkipZigTest;
    // Same bar as the router: the kernel replaces four dispatches, so it has
    // to replace their arithmetic exactly or it is a different model. Covers
    // the negative/positive/extreme branches of MLX's LogAddExp.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0xA11CE00D);
    const rnd = prng.random();
    attn_gate_fused_override = true;
    defer attn_gate_fused_override = null;

    const B: c_int = 1;
    const NH: c_int = 48;
    const HD: c_int = 128;
    for ([_]c_int{ 1, 7 }) |S| {
        const an: usize = @intCast(B * S * NH * HD);
        const gn: usize = @intCast(B * S * NH);

        const abuf = try allocator.alloc(f32, an);
        defer allocator.free(abuf);
        for (abuf) |*v| v.* = (rnd.float(f32) - 0.5) * 3.0;
        const gbuf = try allocator.alloc(f32, gn);
        defer allocator.free(gbuf);
        // Span the branches: large negative (softplus ~ 0), around 0, large
        // positive (softplus ~ x), plus random.
        for (gbuf, 0..) |*v, i| v.* = switch (i % 4) {
            0 => -40.0,
            1 => (rnd.float(f32) - 0.5) * 0.5,
            2 => 30.0,
            else => (rnd.float(f32) - 0.5) * 12.0,
        };

        const ash = [_]c_int{ B, S, NH * HD };
        const a32 = mlx.mlx_array_new_data(abuf.ptr, &ash, 3, .float32);
        defer _ = mlx.mlx_array_free(a32);
        var attn = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(attn);
        try mlx.check(mlx.mlx_astype(&attn, a32, .bfloat16, s));

        const gsh = [_]c_int{ B, S, NH };
        const g32 = mlx.mlx_array_new_data(gbuf.ptr, &gsh, 3, .float32);
        defer _ = mlx.mlx_array_free(g32);
        var glog = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(glog);
        try mlx.check(mlx.mlx_astype(&glog, g32, .bfloat16, s));

        // Reference: the exact op chain the attention path used before the kernel.
        var g_f32 = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(g_f32);
        try mlx.check(mlx.mlx_astype(&g_f32, glog, .float32, s));
        const zero = mlx.mlx_array_new_float(0.0);
        defer _ = mlx.mlx_array_free(zero);
        var g_sp = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(g_sp);
        try mlx.check(mlx.mlx_logaddexp(&g_sp, zero, g_f32, s));
        var g_bf = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(g_bf);
        try mlx.check(mlx.mlx_astype(&g_bf, g_sp, .bfloat16, s));
        const g4 = [_]c_int{ B, S, NH, 1 };
        var g_r = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(g_r);
        try mlx.check(mlx.mlx_reshape(&g_r, g_bf, &g4, 4, s));
        const a4 = [_]c_int{ B, S, NH, HD };
        var attn4 = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(attn4);
        try mlx.check(mlx.mlx_reshape(&attn4, attn, &a4, 4, s));
        var ref4 = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(ref4);
        try mlx.check(mlx.mlx_multiply(&ref4, attn4, g_r, s));

        const got = (try fusedAttnGate(s, attn, glog, NH, HD)) orelse return error.FusedGateDeclined;
        defer _ = mlx.mlx_array_free(got);

        const ref_host = try allocator.alloc(f32, an);
        defer allocator.free(ref_host);
        const got_host = try allocator.alloc(f32, an);
        defer allocator.free(got_host);
        try testReadF32(ref4, ref_host, s);
        try testReadF32(got, got_host, s);
        try testing.expectEqualSlices(f32, ref_host, got_host);
    }
}

test "fused SwiGLU is bit-identical to the sigmoid+multiply+multiply chain" {
    // The reason this kernel exists instead of extending mlx_compile to the
    // silu arm: the compiled fusion is NOT bit-identical (greedy diverged at
    // token ~55). Assert what the compiled path could not.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x51117001);
    const rnd = prng.random();
    swiglu_fused_override = true;
    defer swiglu_fused_override = null;

    // Sizes that are and are not multiples of the threadgroup, so the grid
    // round-up and the kernel's bound check are both exercised.
    for ([_]c_int{ 8, 512, 4096, 4097 }) |n| {
        for ([_]mlx.mlx_dtype{ .bfloat16, .float16 }) |dt| {
            const cnt: usize = @intCast(n);
            const gbuf = try allocator.alloc(f32, cnt);
            defer allocator.free(gbuf);
            const ubuf = try allocator.alloc(f32, cnt);
            defer allocator.free(ubuf);
            for (gbuf, 0..) |*v, i| v.* = switch (i % 5) {
                0 => -30.0,
                1 => 25.0,
                2 => 0.0,
                else => (rnd.float(f32) - 0.5) * 10.0,
            };
            for (ubuf) |*v| v.* = (rnd.float(f32) - 0.5) * 4.0;

            const sh = [_]c_int{n};
            const g32 = mlx.mlx_array_new_data(gbuf.ptr, &sh, 1, .float32);
            defer _ = mlx.mlx_array_free(g32);
            const u32a = mlx.mlx_array_new_data(ubuf.ptr, &sh, 1, .float32);
            defer _ = mlx.mlx_array_free(u32a);
            var gate = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(gate);
            try mlx.check(mlx.mlx_astype(&gate, g32, dt, s));
            var up = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(up);
            try mlx.check(mlx.mlx_astype(&up, u32a, dt, s));

            // Reference: exactly the ops computeGeglu's fallback issues.
            var sig = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(sig);
            try mlx.check(mlx.mlx_sigmoid(&sig, gate, s));
            var act = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(act);
            try mlx.check(mlx.mlx_multiply(&act, gate, sig, s));
            var ref = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(ref);
            try mlx.check(mlx.mlx_multiply(&ref, act, up, s));

            const got = (try fusedSwiGLU(s, gate, up)) orelse return error.FusedSwigluDeclined;
            defer _ = mlx.mlx_array_free(got);

            const ref_host = try allocator.alloc(f32, cnt);
            defer allocator.free(ref_host);
            const got_host = try allocator.alloc(f32, cnt);
            defer allocator.free(got_host);
            try testReadF32(ref, ref_host, s);
            try testReadF32(got, got_host, s);
            try testing.expectEqualSlices(f32, ref_host, got_host);
        }
    }
}

test "fused SwiGLU config cache keys on the SHAPE, not the element count (restore crash)" {
    // Live 2026-07-29: a 16-token hot-cache-restore suffix prefill
    // XS killed the server with "[matmul] (1,16,512) vs (8192,2048)". A MoE
    // layer's SwiGLU at 16 tokens is (1,16,512) = 8192 elements - the SAME
    // count, rank and dtype as a dense mlp_only layer at decode (1,1,8192).
    // The config cache was keyed on {n, tg, ndim, dtype}, so the second call
    // reused a config whose baked OUTPUT SHAPE was the first caller's, and
    // the dense down-proj matmul died on the mislabeled activation. The key
    // must be the full shape; equal products are not equal shapes.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    swiglu_fused_override = true;
    defer swiglu_fused_override = null;

    const shapes = [2][3]c_int{ .{ 1, 16, 512 }, .{ 1, 1, 8192 } };
    for (shapes) |sh| {
        const cnt: usize = 8192;
        const buf = try allocator.alloc(f32, cnt);
        defer allocator.free(buf);
        for (buf, 0..) |*v, i| v.* = @as(f32, @floatFromInt(i % 7)) - 3.0;
        const a32 = mlx.mlx_array_new_data(buf.ptr, &sh, 3, .float32);
        defer _ = mlx.mlx_array_free(a32);
        var gate = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(gate);
        try mlx.check(mlx.mlx_astype(&gate, a32, .bfloat16, s));

        const got = (try fusedSwiGLU(s, gate, gate)) orelse return error.FusedSwigluDeclined;
        defer _ = mlx.mlx_array_free(got);
        try mlx.check(mlx.mlx_array_eval(got));
        const osh = mlx.getShape(got);
        try testing.expectEqualSlices(c_int, &sh, osh);
    }
}

test "fused QKV concatenation is bit-identical to three separate projections" {
    // A weight-layout fusion, so the bar is exact equality, not no-worse-than:
    // each output element is the same dot product over the same contracted axis
    // in the same order. Covers the dense-bf16 layout (weights pre-transposed
    // to [in, out], joined on axis 1) and the quantized layout ([out, in_packed]
    // with scales and biases, joined on axis 0).
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x9BC1D3F7);
    const rnd = prng.random();
    fused_qkv_override = true;
    defer fused_qkv_override = null;

    // A WIDE contraction dim on purpose: the layout bug this pins changes the
    // gemv's accumulation order, and over 256 terms the two orders happened to
    // agree in bf16. At 2048 they do not.
    const IN: c_int = 2048;
    const Q_OUT: c_int = 128;
    const KV_OUT: c_int = 64;
    const S_LEN: c_int = 5; // > 1 so the prefill slice/reshape path is exercised

    for ([_]bool{ true, false }) |dense| {
        const mk = struct {
            fn dense_w(out_dim: c_int, in_dim: c_int, r: std.Random, alloc: std.mem.Allocator, str: mlx.mlx_stream) !mlx.mlx_array {
                // Loaded [out, in] then pre-transposed to [in, out], as
                // maybeTransposeForBf16 leaves it.
                const buf = try alloc.alloc(f32, @intCast(out_dim * in_dim));
                defer alloc.free(buf);
                for (buf) |*v| v.* = (r.float(f32) - 0.5) * 0.4;
                const sh = [_]c_int{ out_dim, in_dim };
                const a32 = mlx.mlx_array_new_data(buf.ptr, &sh, 2, .float32);
                defer _ = mlx.mlx_array_free(a32);
                var bf = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(bf);
                try mlx.check(mlx.mlx_astype(&bf, a32, .bfloat16, str));
                return transposeBf16Weight(bf, str);
            }
        };

        var qw: mlx.mlx_array = undefined;
        var kw: mlx.mlx_array = undefined;
        var vw: mlx.mlx_array = undefined;
        var qs = mlx.mlx_array{ .ctx = null };
        var ks = mlx.mlx_array{ .ctx = null };
        var vs = mlx.mlx_array{ .ctx = null };
        var qb = mlx.mlx_array{ .ctx = null };
        var kb = mlx.mlx_array{ .ctx = null };
        var vb = mlx.mlx_array{ .ctx = null };
        defer {
            for ([_]mlx.mlx_array{ qw, kw, vw, qs, ks, vs, qb, kb, vb }) |h| {
                if (h.ctx != null) _ = mlx.mlx_array_free(h);
            }
        }

        if (dense) {
            qw = try mk.dense_w(Q_OUT, IN, rnd, allocator, s);
            kw = try mk.dense_w(KV_OUT, IN, rnd, allocator, s);
            vw = try mk.dense_w(KV_OUT, IN, rnd, allocator, s);
        } else {
            const outs = [_]c_int{ Q_OUT, KV_OUT, KV_OUT };
            var made: [3]struct { w: mlx.mlx_array, s: mlx.mlx_array, b: mlx.mlx_array } = undefined;
            for (outs, 0..) |od, i| {
                const buf = try allocator.alloc(f32, @intCast(od * IN));
                defer allocator.free(buf);
                for (buf) |*v| v.* = (rnd.float(f32) - 0.5) * 0.4;
                const sh = [_]c_int{ od, IN };
                const a32 = mlx.mlx_array_new_data(buf.ptr, &sh, 2, .float32);
                defer _ = mlx.mlx_array_free(a32);
                var bf = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(bf);
                try mlx.check(mlx.mlx_astype(&bf, a32, .bfloat16, s));
                var triple = mlx.mlx_vector_array_new();
                defer _ = mlx.mlx_vector_array_free(triple);
                try mlx.check(mlx.mlx_quantize(&triple, bf, mlx.mlx_optional_int.some(64), mlx.mlx_optional_int.some(4), "affine", .{}, s));
                var w = mlx.mlx_array_new();
                try mlx.check(mlx.mlx_vector_array_get(&w, triple, 0));
                var sc = mlx.mlx_array_new();
                try mlx.check(mlx.mlx_vector_array_get(&sc, triple, 1));
                var bi = mlx.mlx_array_new();
                try mlx.check(mlx.mlx_vector_array_get(&bi, triple, 2));
                made[i] = .{ .w = w, .s = sc, .b = bi };
            }
            qw = made[0].w;
            qs = made[0].s;
            qb = made[0].b;
            kw = made[1].w;
            ks = made[1].s;
            kb = made[1].b;
            vw = made[2].w;
            vs = made[2].s;
            vb = made[2].b;
        }

        const fa = FullAttnWeights{
            .q_w = qw,
            .q_s = qs,
            .q_b = qb,
            .k_w = kw,
            .k_s = ks,
            .k_b = kb,
            .v_w = vw,
            .v_s = vs,
            .v_b = vb,
            .o_w = .{ .ctx = null },
            .o_s = .{ .ctx = null },
            .o_b = .{ .ctx = null },
            .q_norm = .{ .ctx = null },
            .k_norm = .{ .ctx = null },
        };
        const qp = QuantParams{ .bits = 4, .group_size = 64, .mode = .affine };
        const fused = (try buildFusedQkv(s, &fa, qp, qp, qp)) orelse return error.FusedQkvDeclined;
        defer _ = mlx.mlx_array_free(fused.w);
        defer if (fused.base.ctx != null) {
            _ = mlx.mlx_array_free(fused.base);
        };
        defer if (fused.s.ctx != null) {
            _ = mlx.mlx_array_free(fused.s);
        };
        defer if (fused.b.ctx != null) {
            _ = mlx.mlx_array_free(fused.b);
        };

        const xn: usize = @intCast(S_LEN * IN);
        const xbuf = try allocator.alloc(f32, xn);
        defer allocator.free(xbuf);
        for (xbuf) |*v| v.* = (rnd.float(f32) - 0.5) * 2.0;
        const xsh = [_]c_int{ 1, S_LEN, IN };
        const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xsh, 3, .float32);
        defer _ = mlx.mlx_array_free(x32);
        var x = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(x);
        try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));

        var joined = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(joined);
        if (dense) {
            try mlx.check(mlx.mlx_matmul(&joined, x, fused.w, s));
        } else {
            const got = try qmatmulBits(x, fused.w, fused.s, fused.b, 4, 64, .affine, s);
            _ = mlx.mlx_array_free(joined);
            joined = got;
        }

        const widths = [_]c_int{ Q_OUT, KV_OUT, KV_OUT };
        const ws = [_]mlx.mlx_array{ qw, kw, vw };
        const ss = [_]mlx.mlx_array{ qs, ks, vs };
        const bs = [_]mlx.mlx_array{ qb, kb, vb };
        var off: c_int = 0;
        for (widths, ws, ss, bs) |width, w, sc, bi| {
            var ref = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(ref);
            if (dense) {
                try mlx.check(mlx.mlx_matmul(&ref, x, w, s));
            } else {
                const r = try qmatmulBits(x, w, sc, bi, 4, 64, .affine, s);
                _ = mlx.mlx_array_free(ref);
                ref = r;
            }
            var part = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(part);
            try sliceQkvPart(&part, joined, off, width, s);

            const cnt: usize = @intCast(S_LEN * width);
            const h1 = try allocator.alloc(f32, cnt);
            defer allocator.free(h1);
            const h2 = try allocator.alloc(f32, cnt);
            defer allocator.free(h2);
            try testReadF32(ref, h1, s);
            try testReadF32(part, h2, s);
            try testing.expectEqualSlices(f32, h1, h2);
            off += width;
        }
    }
}

test "fused row projections are bit-identical to the separate matmuls at decode widths" {
    // Bar: for M in 1..FUSED_ROWS_MAX_M the joined matmul's slices equal the
    // separate matmuls byte for byte, and each rewritten VIEW equals its
    // original at a prefill width too (the separate path must not move).
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0xF05ED);
    const rnd = prng.random();
    const K: c_int = 2560;
    const Q = struct { w: mlx.mlx_array, sc: mlx.mlx_array, bi: mlx.mlx_array };
    const quant = struct {
        fn f(a: std.mem.Allocator, r: std.Random, st: mlx.mlx_stream, rows: c_int, cols: c_int) !Q {
            const buf = try a.alloc(f32, @intCast(rows * cols));
            defer a.free(buf);
            for (buf) |*v| v.* = (r.float(f32) - 0.5) * 0.2;
            const sh = [_]c_int{ rows, cols };
            const w32 = mlx.mlx_array_new_data(buf.ptr, &sh, 2, .float32);
            defer _ = mlx.mlx_array_free(w32);
            var wb = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wb);
            try mlx.check(mlx.mlx_astype(&wb, w32, .bfloat16, st));
            var triple = mlx.mlx_vector_array_new();
            defer _ = mlx.mlx_vector_array_free(triple);
            try mlx.check(mlx.mlx_quantize(&triple, wb, mlx.mlx_optional_int.some(64), mlx.mlx_optional_int.some(4), "affine", .{}, st));
            var q: Q = undefined;
            q.w = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_vector_array_get(&q.w, triple, 0));
            q.sc = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_vector_array_get(&q.sc, triple, 1));
            q.bi = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_vector_array_get(&q.bi, triple, 2));
            return q;
        }
    }.f;
    const groups = [_][]const c_int{ &.{ 4096, 1024, 1024, 16 }, &.{ 2048, 512, 512 }, &.{ 10240, 10240 }, &.{ 10240, 6144, 48, 48 } };
    for (groups) |widths| {
        var orig: [4]Q = undefined;
        var live: [4]Q = undefined;
        for (widths, 0..) |n, i| {
            orig[i] = try quant(allocator, rnd, s, n, K);
            live[i] = orig[i];
        }
        defer for (orig[0..widths.len]) |q| {
            _ = mlx.mlx_array_free(q.w);
            _ = mlx.mlx_array_free(q.sc);
            _ = mlx.mlx_array_free(q.bi);
        };
        var parts: [4][3]*mlx.mlx_array = undefined;
        for (0..widths.len) |i| parts[i] = .{ &live[i].w, &live[i].sc, &live[i].bi };
        const fused = (try fuseRowGroup(parts[0..widths.len], s)) orelse return error.FusedRowsDeclined;
        defer {
            _ = mlx.mlx_array_free(fused.w);
            _ = mlx.mlx_array_free(fused.s);
            _ = mlx.mlx_array_free(fused.b);
            for (live[0..widths.len]) |q| {
                _ = mlx.mlx_array_free(q.w);
                _ = mlx.mlx_array_free(q.sc);
                _ = mlx.mlx_array_free(q.bi);
            }
        }
        for ([_]c_int{ 1, 2, 3, 5, 8, 64 }) |m| {
            const xb = try allocator.alloc(f32, @intCast(m * K));
            defer allocator.free(xb);
            for (xb) |*v| v.* = (rnd.float(f32) - 0.5) * 2.0;
            const xsh = [_]c_int{ 1, m, K };
            const x32 = mlx.mlx_array_new_data(xb.ptr, &xsh, 3, .float32);
            defer _ = mlx.mlx_array_free(x32);
            var x = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x);
            try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));
            var y_all = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(y_all);
            if (m <= FUSED_ROWS_MAX_M) y_all = try qmatmulBits(x, fused.w, fused.s, fused.b, 4, 64, .affine, s);
            for (0..widths.len) |i| {
                const ref = try qmatmulBits(x, orig[i].w, orig[i].sc, orig[i].bi, 4, 64, .affine, s);
                defer _ = mlx.mlx_array_free(ref);
                const via_view = try qmatmulBits(x, live[i].w, live[i].sc, live[i].bi, 4, 64, .affine, s);
                defer _ = mlx.mlx_array_free(via_view);
                const cnt: usize = @intCast(m * widths[i]);
                const h1 = try allocator.alloc(f32, cnt);
                defer allocator.free(h1);
                const h2 = try allocator.alloc(f32, cnt);
                defer allocator.free(h2);
                try testReadF32(ref, h1, s);
                try testReadF32(via_view, h2, s);
                try testing.expectEqualSlices(f32, h1, h2);
                if (m <= FUSED_ROWS_MAX_M) {
                    var part = mlx.mlx_array_new();
                    defer _ = mlx.mlx_array_free(part);
                    try fused.part(&part, y_all, i, s);
                    try testReadF32(part, h2, s);
                    try testing.expectEqualSlices(f32, h1, h2);
                }
            }
        }
    }
}

test "fused residual norm chain is bit-identical to the composed ops in every stage combination" {
    // Bar: pre-norm / scale / post-norm on and off in all eight combinations,
    // aligned and ragged widths, rows 1 and 3, bf16 and f32, byte for byte
    // against rms_norm -> add -> multiply -> rms_norm as separate MLX ops.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x5EA3);
    const rnd = prng.random();
    const EPS_PRE: f32 = 1e-5;
    const EPS: f32 = 1e-6;
    const eps_pre = mlx.mlx_array_new_float(EPS_PRE);
    defer _ = mlx.mlx_array_free(eps_pre);
    const eps = mlx.mlx_array_new_float(EPS);
    defer _ = mlx.mlx_array_free(eps);
    const rand = struct {
        fn f(a: std.mem.Allocator, r: std.Random, st: mlx.mlx_stream, shape: []const c_int, scale: f32, offset: f32, dt: mlx.mlx_dtype) !mlx.mlx_array {
            var n: usize = 1;
            for (shape) |d| n *= @intCast(d);
            const buf = try a.alloc(f32, n);
            defer a.free(buf);
            for (buf) |*v| v.* = (r.float(f32) - 0.5) * scale + offset;
            const a32 = mlx.mlx_array_new_data(buf.ptr, shape.ptr, @intCast(shape.len), .float32);
            defer _ = mlx.mlx_array_free(a32);
            var out = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_astype(&out, a32, dt, st));
            return out;
        }
    }.f;
    for ([_]c_int{ 512, 2050, 2560 }) |axis| {
        for ([_]c_int{ 1, 3 }) |rows| {
            for ([_]mlx.mlx_dtype{ .bfloat16, .float32 }) |dt| {
                const sh = [_]c_int{ rows, axis };
                const a = try rand(allocator, rnd, s, &sh, 6.0, 0.0, dt);
                defer _ = mlx.mlx_array_free(a);
                const b = try rand(allocator, rnd, s, &sh, 6.0, 0.0, dt);
                defer _ = mlx.mlx_array_free(b);
                const wsh = [_]c_int{axis};
                const w_pre = try rand(allocator, rnd, s, &wsh, 1.0, 1.0, dt);
                defer _ = mlx.mlx_array_free(w_pre);
                const w_post = try rand(allocator, rnd, s, &wsh, 1.0, 1.0, dt);
                defer _ = mlx.mlx_array_free(w_post);
                const ssh = [_]c_int{1};
                const scale = try rand(allocator, rnd, s, &ssh, 0.5, 0.9, dt);
                defer _ = mlx.mlx_array_free(scale);
                const none = mlx.mlx_array{ .ctx = null };
                for (0..8) |combo| {
                    const pre = combo & 1 != 0;
                    const scl = combo & 2 != 0;
                    const post = combo & 4 != 0;
                    if (!pre and !scl and !post) continue;
                    // Reference chain.
                    var nb = mlx.mlx_array_new();
                    defer _ = mlx.mlx_array_free(nb);
                    if (pre) try mlx.check(mlx.mlx_fast_rms_norm(&nb, b, w_pre, EPS_PRE, s)) else _ = mlx.mlx_array_set(&nb, b);
                    var sum = mlx.mlx_array_new();
                    defer _ = mlx.mlx_array_free(sum);
                    try mlx.check(mlx.mlx_add(&sum, a, nb, s));
                    var res = mlx.mlx_array_new();
                    defer _ = mlx.mlx_array_free(res);
                    if (scl) try mlx.check(mlx.mlx_multiply(&res, sum, scale, s)) else _ = mlx.mlx_array_set(&res, sum);
                    var ref_norm = mlx.mlx_array_new();
                    defer _ = mlx.mlx_array_free(ref_norm);
                    if (post) try mlx.check(mlx.mlx_fast_rms_norm(&ref_norm, res, w_post, EPS, s));

                    const got = (try fusedResidualNorm(s, a, b, .{ .w1 = if (pre) w_pre else none, .eps1 = eps_pre, .scale = if (scl) scale else none, .w_post = if (post) w_post else none, .eps = eps })) orelse return error.FusedResidualNormDeclined;
                    defer _ = mlx.mlx_array_free(got.sum);
                    defer if (post) {
                        _ = mlx.mlx_array_free(got.normed);
                    };
                    try testing.expect((got.normed.ctx != null) == post);

                    const cnt: usize = @intCast(rows * axis);
                    const h1 = try allocator.alloc(f32, cnt);
                    defer allocator.free(h1);
                    const h2 = try allocator.alloc(f32, cnt);
                    defer allocator.free(h2);
                    try testReadF32(res, h1, s);
                    try testReadF32(got.sum, h2, s);
                    try testing.expectEqualSlices(f32, h1, h2);
                    if (post) {
                        try testReadF32(ref_norm, h1, s);
                        try testReadF32(got.normed, h2, s);
                        try testing.expectEqualSlices(f32, h1, h2);
                    }
                }
            }
        }
    }
}

fn parityRand(rnd: std.Random, shape: []const c_int, scale: f32, dt: mlx.mlx_dtype, s: mlx.mlx_stream) !mlx.mlx_array {
    const b = try attn256RandBf16Scaled(rnd, shape, scale, s);
    defer _ = mlx.mlx_array_free(b);
    var out = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_astype(&out, b, dt, s));
    return out;
}

test "fused clamped swiglu is bit-identical to the clampedSwiGLU chain" {
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0x61A5);
    const rnd = prng.random();
    // Spread past +-10 so both clamps bite.
    const gate = try parityRand(rnd, &.{ 3, 7, 2048 }, 16.0, .bfloat16, s);
    defer _ = mlx.mlx_array_free(gate);
    const up = try parityRand(rnd, &.{ 3, 7, 2048 }, 16.0, .bfloat16, s);
    defer _ = mlx.mlx_array_free(up);
    const want = try clampedSwiGLU(s, gate, up, 10.0);
    defer _ = mlx.mlx_array_free(want);
    const got = (try fusedClampedSwiGLU(s, gate, up, 10.0)) orelse return error.SkipZigTest;
    defer _ = mlx.mlx_array_free(got);
    var eq = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(eq);
    try mlx.check(mlx.mlx_array_equal(&eq, want, got, false, s));
    try mlx.check(mlx.mlx_array_eval(eq));
    var eq_v: bool = false;
    try mlx.check(mlx.mlx_array_item_bool(&eq_v, eq));
    try testing.expect(eq_v);
}

test "joined swiglu is bit-identical to fusedSwiGLU over the two halves" {
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0x5316);
    const rnd = prng.random();
    for ([_]c_int{ 1, 16, 33 }) |rows| {
        const both = try parityRand(rnd, &.{ 1, rows, 2 * 1088 }, 6.0, .bfloat16, s);
        defer _ = mlx.mlx_array_free(both);
        var gate = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(gate);
        var up = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(up);
        try sliceQkvPart(&gate, both, 0, 1088, s);
        try sliceQkvPart(&up, both, 1088, 1088, s);
        const ref = (try fusedSwiGLU(s, gate, up)) orelse return error.Declined;
        defer _ = mlx.mlx_array_free(ref);
        const got = (try swigluJoined(s, both)) orelse return error.Declined;
        defer _ = mlx.mlx_array_free(got);
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(got, ref, s));
    }
}

test "strided sigmoid gate is bit-identical to mlx_sigmoid + multiply over a transposed output and a split gate" {
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0x6A7E);
    const rnd = prng.random();
    for ([_]c_int{ 1, 16 }) |rows| {
        const heads: c_int = 24;
        const hd: c_int = 256;
        const out_bhsd = try parityRand(rnd, &.{ 1, heads, rows, hd }, 4.0, .bfloat16, s);
        defer _ = mlx.mlx_array_free(out_bhsd);
        var x = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(x);
        try mlx.check(mlx.mlx_transpose_axes(&x, out_bhsd, &[_]c_int{ 0, 2, 1, 3 }, 4, s));
        const qg = try parityRand(rnd, &.{ 1, rows, heads, 2 * hd }, 12.0, .bfloat16, s);
        defer _ = mlx.mlx_array_free(qg);
        var g = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(g);
        try mlx.check(mlx.mlx_slice(&g, qg, &[_]c_int{ 0, 0, 0, hd }, 4, &[_]c_int{ 1, rows, heads, 2 * hd }, 4, &[_]c_int{ 1, 1, 1, 1 }, 4, s));
        var sig = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(sig);
        try mlx.check(mlx.mlx_sigmoid(&sig, g, s));
        var ref = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(ref);
        try mlx.check(mlx.mlx_multiply(&ref, x, sig, s));
        const got = (try stridedSigmoidGateMul(s, x, g)) orelse return error.FusedDeclined;
        defer _ = mlx.mlx_array_free(got);
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(got, ref, s));
        // A metal_kernel helper declines off the GPU stream.
        const cpu = mlx.mlx_default_cpu_stream_new();
        defer _ = mlx.mlx_stream_free(cpu);
        try std.testing.expect((try stridedSigmoidGateMul(cpu, x, g)) == null);
    }
}

test "fused sigmoid gate is bit-identical to mlx_sigmoid + broadcast multiply, per-head and elementwise" {
    const s = mlx.gpuStream();
    swiglu_fused_override = true;
    defer swiglu_fused_override = null;
    var prng = std.Random.DefaultPrng.init(0x51663);
    const rnd = prng.random();
    const heads: c_int = 16;
    const hd: c_int = 256;
    for ([_]bool{ true, false }) |headwise| {
        const x_shape = [_]c_int{ 1, 1, heads * hd };
        const x = try parityRand(rnd, &x_shape, 4.0, .bfloat16, s);
        defer _ = mlx.mlx_array_free(x);
        const g_shape = [_]c_int{ 1, 1, if (headwise) heads else heads * hd };
        const g = try parityRand(rnd, &g_shape, 12.0, .bfloat16, s);
        defer _ = mlx.mlx_array_free(g);
        var sig = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(sig);
        try mlx.check(mlx.mlx_sigmoid(&sig, g, s));
        var ref = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(ref);
        if (headwise) {
            const x4 = [_]c_int{ 1, 1, heads, hd };
            const g4 = [_]c_int{ 1, 1, heads, 1 };
            var xr = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(xr);
            try mlx.check(mlx.mlx_reshape(&xr, x, &x4, 4, s));
            var gr = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(gr);
            try mlx.check(mlx.mlx_reshape(&gr, sig, &g4, 4, s));
            var prod = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(prod);
            try mlx.check(mlx.mlx_multiply(&prod, xr, gr, s));
            try mlx.check(mlx.mlx_reshape(&ref, prod, &x_shape, 3, s));
        } else {
            try mlx.check(mlx.mlx_multiply(&ref, x, sig, s));
        }
        const got = (try fusedSigmoidGateMul(s, x, g, if (headwise) heads else 0)) orelse return error.FusedDeclined;
        defer _ = mlx.mlx_array_free(got);
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(got, ref, s));
    }
}

test "fused gelu-ple projection matches gelu table -> multiply -> quantized_matmul to bf16 rounding" {
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    swiglu_fused_override = true;
    defer swiglu_fused_override = null;
    var prng = std.Random.DefaultPrng.init(0x9E1E);
    const rnd = prng.random();
    var xfm: Transformer = undefined;
    xfm.s = s;
    xfm.compiled_gelu = null;
    xfm.three = bf16Scalar(3.0, s);
    defer _ = mlx.mlx_array_free(xfm.three.?);
    xfm.gelu_inner = bf16Scalar(0.044715, s);
    defer _ = mlx.mlx_array_free(xfm.gelu_inner.?);
    xfm.gelu_coeff = bf16Scalar(0.7978845608028654, s);
    defer _ = mlx.mlx_array_free(xfm.gelu_coeff.?);
    xfm.one = bf16Scalar(1.0, s);
    defer _ = mlx.mlx_array_free(xfm.one);
    xfm.half = bf16Scalar(0.5, s);
    defer _ = mlx.mlx_array_free(xfm.half);
    const table = (try xfm.geluTanhTable(.bfloat16)) orelse return error.NoTable;
    const HID: c_int = 2560;
    const PD: c_int = 256;
    for ([_]f32{ 1.0, 12.0, 60.0 }) |scale| {
        const wb = try parityRand(rnd, &.{ HID, PD }, 1.0, .bfloat16, s);
        defer _ = mlx.mlx_array_free(wb);
        var triple = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(triple);
        try mlx.check(mlx.mlx_quantize(&triple, wb, mlx.mlx_optional_int.some(64), mlx.mlx_optional_int.some(4), "affine", .{}, s));
        var pw = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(pw);
        var ps = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(ps);
        var pb = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(pb);
        try mlx.check(mlx.mlx_vector_array_get(&pw, triple, 0));
        try mlx.check(mlx.mlx_vector_array_get(&ps, triple, 1));
        try mlx.check(mlx.mlx_vector_array_get(&pb, triple, 2));
        const g = try parityRand(rnd, &.{ 1, 1, PD }, scale, .bfloat16, s);
        defer _ = mlx.mlx_array_free(g);
        const ple = try parityRand(rnd, &.{ 1, 1, PD }, 4.0, .bfloat16, s);
        defer _ = mlx.mlx_array_free(ple);
        const act = try xfm.gelu(g);
        defer _ = mlx.mlx_array_free(act);
        var gated = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(gated);
        try mlx.check(mlx.mlx_multiply(&gated, act, ple, s));
        const ref = try qmatmulBits(gated, pw, ps, pb, 4, 64, .affine, s);
        defer _ = mlx.mlx_array_free(ref);
        const got = (try fusedGeluPleProj(s, g, ple, table, pw, ps, pb, .{ .bits = 4, .group_size = 64, .mode = .affine })) orelse return error.FusedDeclined;
        defer _ = mlx.mlx_array_free(got);
        // The kernel adds each run of 4 inputs in bf16, as MLX's qmv did on bfloat16_t; the stock kernel of this build
        // rounds that sum differently, so the two differ by a few bf16 ulps. A wrong index, scale or bias is off by far more.
        var zeros = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(zeros);
        try mlx.check(mlx.mlx_zeros(&zeros, &[_]c_int{ 1, 1, HID }, 3, .bfloat16, s));
        const mag = try attn256MaxDiff(ref, zeros, s);
        try std.testing.expect(mag > 0);
        try std.testing.expect(try attn256MaxDiff(got, ref, s) <= 2e-2 * mag);
    }
    _ = allocator;
}

test "fused residual norm chain: two normed branches, combine norm and both post-norms" {
    // The Gemma MoE tail shape: res = (a + wc*rms(w1*rms(b1) + w2*rms(b2))) * s,
    // out = wp*rms(res), out2 = wp2*rms(res); byte for byte against the ops.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x2B2B);
    const rnd = prng.random();
    const EPS: f32 = 1e-6;
    const eps = mlx.mlx_array_new_float(EPS);
    defer _ = mlx.mlx_array_free(eps);
    const axis: c_int = 2816;
    const rows: c_int = 1;
    const sh = [_]c_int{ rows, axis };
    const wsh = [_]c_int{axis};
    const ssh = [_]c_int{1};
    const mk = struct {
        fn f(a: std.mem.Allocator, r: std.Random, st: mlx.mlx_stream, shape: []const c_int, scale: f32, offset: f32) !mlx.mlx_array {
            var n: usize = 1;
            for (shape) |d| n *= @intCast(d);
            const buf = try a.alloc(f32, n);
            defer a.free(buf);
            for (buf) |*v| v.* = (r.float(f32) - 0.5) * scale + offset;
            const a32 = mlx.mlx_array_new_data(buf.ptr, shape.ptr, @intCast(shape.len), .float32);
            defer _ = mlx.mlx_array_free(a32);
            var out = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_astype(&out, a32, .bfloat16, st));
            return out;
        }
    }.f;
    const a = try mk(allocator, rnd, s, &sh, 6.0, 0.0);
    defer _ = mlx.mlx_array_free(a);
    const b1 = try mk(allocator, rnd, s, &sh, 6.0, 0.0);
    defer _ = mlx.mlx_array_free(b1);
    const b2 = try mk(allocator, rnd, s, &sh, 6.0, 0.0);
    defer _ = mlx.mlx_array_free(b2);
    var ws: [5]mlx.mlx_array = undefined;
    for (&ws) |*w| w.* = try mk(allocator, rnd, s, &wsh, 1.0, 1.0);
    defer for (ws) |w| {
        _ = mlx.mlx_array_free(w);
    };
    const scale = try mk(allocator, rnd, s, &ssh, 0.5, 0.9);
    defer _ = mlx.mlx_array_free(scale);

    var n1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(n1);
    try mlx.check(mlx.mlx_fast_rms_norm(&n1, b1, ws[0], EPS, s));
    var n2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(n2);
    try mlx.check(mlx.mlx_fast_rms_norm(&n2, b2, ws[1], EPS, s));
    var c = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(c);
    try mlx.check(mlx.mlx_add(&c, n1, n2, s));
    var nc = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(nc);
    try mlx.check(mlx.mlx_fast_rms_norm(&nc, c, ws[2], EPS, s));
    var sum = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(sum);
    try mlx.check(mlx.mlx_add(&sum, a, nc, s));
    var res = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(res);
    try mlx.check(mlx.mlx_multiply(&res, sum, scale, s));
    var o1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o1);
    try mlx.check(mlx.mlx_fast_rms_norm(&o1, res, ws[3], EPS, s));
    var o2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(o2);
    try mlx.check(mlx.mlx_fast_rms_norm(&o2, res, ws[4], EPS, s));

    const got = (try fusedResidualNorm(s, a, b1, .{ .b2 = b2, .w1 = ws[0], .eps1 = eps, .w2 = ws[1], .eps2 = eps, .wc = ws[2], .epsc = eps, .scale = scale, .w_post = ws[3], .w_post2 = ws[4], .eps = eps })) orelse return error.FusedResidualNormDeclined;
    defer _ = mlx.mlx_array_free(got.sum);
    defer _ = mlx.mlx_array_free(got.normed);
    defer _ = mlx.mlx_array_free(got.normed2);
    const cnt: usize = @intCast(rows * axis);
    const h1 = try allocator.alloc(f32, cnt);
    defer allocator.free(h1);
    const h2 = try allocator.alloc(f32, cnt);
    defer allocator.free(h2);
    const pairs = [_][2]mlx.mlx_array{ .{ res, got.sum }, .{ o1, got.normed }, .{ o2, got.normed2 } };
    for (pairs) |pr| {
        try testReadF32(pr[0], h1, s);
        try testReadF32(pr[1], h2, s);
        try testing.expectEqualSlices(f32, h1, h2);
    }
}

test "fused GELU-tanh gate is bit-identical to the current GELU path times up" {
    // The table is built from `Transformer.gelu` itself, so the bar is the
    // multiply: table[x] * up over every bf16 x and a few up values.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    swiglu_fused_override = true;
    defer swiglu_fused_override = null;
    var xfm: Transformer = undefined;
    xfm.s = s;
    xfm.compiled_gelu = null;
    xfm.three = bf16Scalar(3.0, s);
    defer _ = mlx.mlx_array_free(xfm.three.?);
    xfm.gelu_inner = bf16Scalar(0.044715, s);
    defer _ = mlx.mlx_array_free(xfm.gelu_inner.?);
    xfm.gelu_coeff = bf16Scalar(0.7978845608028654, s);
    defer _ = mlx.mlx_array_free(xfm.gelu_coeff.?);
    xfm.one = bf16Scalar(1.0, s);
    defer _ = mlx.mlx_array_free(xfm.one);
    xfm.half = bf16Scalar(0.5, s);
    defer _ = mlx.mlx_array_free(xfm.half);
    const gate = try all16BitPatterns(s, .bfloat16, allocator);
    defer _ = mlx.mlx_array_free(gate);
    for ([_]f32{ 1.0, -0.375, 3.140625 }) |uv| {
        const uscalar = try scalarOf(uv, .bfloat16, s);
        defer _ = mlx.mlx_array_free(uscalar);
        var up_full = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(up_full);
        try mlx.check(mlx.mlx_broadcast_to(&up_full, uscalar, mlx.getShape(gate).ptr, 1, s));
        var up = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(up);
        try mlx.check(mlx.mlx_contiguous(&up, up_full, false, s));
        const act = try xfm.gelu(gate);
        defer _ = mlx.mlx_array_free(act);
        var ref = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(ref);
        try mlx.check(mlx.mlx_multiply(&ref, act, up, s));
        const got = (try xfm.fusedGeluTanhMul(gate, up)) orelse return error.FusedGeluDeclined;
        defer _ = mlx.mlx_array_free(got);
        var eq = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(eq);
        try mlx.check(mlx.mlx_array_equal(&eq, ref, got, true, s));
        try mlx.check(mlx.mlx_array_eval(eq));
        var eq_v: bool = false;
        try mlx.check(mlx.mlx_array_item_bool(&eq_v, eq));
        try testing.expect(eq_v);
    }
}

test "fused residual+RMSNorm is bit-identical to mlx_add + mlx_fast_rms_norm" {
    // Same bar as the other fusions, and the same reason it is reachable: the
    // kernel keeps MLX's launch geometry, so the reduction is the same TREE and
    // not merely the same sum. Widths chosen to hit the aligned path (2048,
    // 512), the ragged tail (2050 - not a multiple of 4), and a non-power-of-2
    // axis (5120) where `acc / axis_size` could differ if a compiler turned the
    // divide into a reciprocal multiply.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x0DDBA11);
    const rnd = prng.random();
    add_rmsnorm_override = true;
    defer add_rmsnorm_override = null;

    const EPS: f32 = 1e-6;
    const eps_arr = mlx.mlx_array_new_float(EPS);
    defer _ = mlx.mlx_array_free(eps_arr);

    for ([_]c_int{ 512, 1536, 2048, 2050 }) |axis| {
        for ([_]c_int{ 1, 3 }) |rows| {
            for ([_]mlx.mlx_dtype{ .bfloat16, .float32 }) |dt| {
                const cnt: usize = @intCast(rows * axis);
                const abuf = try allocator.alloc(f32, cnt);
                defer allocator.free(abuf);
                const bbuf = try allocator.alloc(f32, cnt);
                defer allocator.free(bbuf);
                const wbuf = try allocator.alloc(f32, @intCast(axis));
                defer allocator.free(wbuf);
                for (abuf) |*v| v.* = (rnd.float(f32) - 0.5) * 6.0;
                for (bbuf) |*v| v.* = (rnd.float(f32) - 0.5) * 6.0;
                for (wbuf) |*v| v.* = 0.5 + rnd.float(f32);

                const sh = [_]c_int{ rows, axis };
                const wsh = [_]c_int{axis};
                const a32 = mlx.mlx_array_new_data(abuf.ptr, &sh, 2, .float32);
                defer _ = mlx.mlx_array_free(a32);
                const b32 = mlx.mlx_array_new_data(bbuf.ptr, &sh, 2, .float32);
                defer _ = mlx.mlx_array_free(b32);
                const w32 = mlx.mlx_array_new_data(wbuf.ptr, &wsh, 1, .float32);
                defer _ = mlx.mlx_array_free(w32);
                var a = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(a);
                try mlx.check(mlx.mlx_astype(&a, a32, dt, s));
                var b = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(b);
                try mlx.check(mlx.mlx_astype(&b, b32, dt, s));
                var w = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(w);
                try mlx.check(mlx.mlx_astype(&w, w32, dt, s));

                var ref_sum = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(ref_sum);
                try mlx.check(mlx.mlx_add(&ref_sum, a, b, s));
                var ref_norm = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(ref_norm);
                try mlx.check(mlx.mlx_fast_rms_norm(&ref_norm, ref_sum, w, EPS, s));

                const got = (try fusedAddRmsNorm(s, a, b, w, eps_arr)) orelse return error.FusedAddNormDeclined;
                defer _ = mlx.mlx_array_free(got.sum);
                defer _ = mlx.mlx_array_free(got.normed);

                const h1 = try allocator.alloc(f32, cnt);
                defer allocator.free(h1);
                const h2 = try allocator.alloc(f32, cnt);
                defer allocator.free(h2);
                try testReadF32(ref_sum, h1, s);
                try testReadF32(got.sum, h2, s);
                try testing.expectEqualSlices(f32, h1, h2);
                try testReadF32(ref_norm, h1, s);
                try testReadF32(got.normed, h2, s);
                try testing.expectEqualSlices(f32, h1, h2);
            }
        }
    }
}

test "fused residual+RMSNorm declines what it cannot reproduce" {
    const s = mlx.gpuStream();
    add_rmsnorm_override = true;
    defer add_rmsnorm_override = null;
    // mlx_array_new_data COPIES shape-worth of bytes - the buffer must really
    // hold 8192 floats (a 16-float buffer here "passed" by overreading the
    // stack until a layout shift put the guard page in range).
    var buf: [8192]f32 = @splat(0.25);
    // Above RMS_LOOPED_LIMIT mlx switches to a different kernel with a
    // different reduction shape.
    const big = [_]c_int{ 1, 8192 };
    const wbig = [_]c_int{8192};
    const a = mlx.mlx_array_new_data(&buf, &big, 2, .float32);
    defer _ = mlx.mlx_array_free(a);
    const w = mlx.mlx_array_new_data(&buf, &wbig, 1, .float32);
    defer _ = mlx.mlx_array_free(w);
    const eps = mlx.mlx_array_new_float(1e-6);
    defer _ = mlx.mlx_array_free(eps);
    try testing.expect((try fusedAddRmsNorm(s, a, a, w, eps)) == null);
    // Mismatched shapes must decline rather than read out of bounds.
    const s2 = [_]c_int{ 1, 4 };
    const small = mlx.mlx_array_new_data(&buf, &s2, 2, .float32);
    defer _ = mlx.mlx_array_free(small);
    try testing.expect((try fusedAddRmsNorm(s, a, small, w, eps)) == null);
}

test "fused gate+up+SwiGLU expert kernel is bit-identical to the split gatherQmv path" {
    // The split path is `gatherQmv(gate)` + `gatherQmv(up)` + `fusedSwiGLU`.
    // Fusing them may not change a single rounding: each accumulator is still
    // rounded to T before the activation, and the activation is still the
    // table. Covers both dequant arithmetics and both live top-K widths.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x6A7E0FF5);
    const rnd = prng.random();
    gqmv_gateup_override = true;
    defer gqmv_gateup_override = null;
    swiglu_fused_override = true;
    defer swiglu_fused_override = null;

    const E: c_int = 8;
    const N: c_int = 64;
    const K: c_int = 256;
    const TOPK: c_int = 3;

    for ([_]struct { nvfp4: bool, bits: u32, gs: u32 }{
        .{ .nvfp4 = false, .bits = 4, .gs = 64 },
        .{ .nvfp4 = true, .bits = 4, .gs = 16 },
        .{ .nvfp4 = false, .bits = 3, .gs = 128 },
    }) |cfg| {
        const nvfp4 = cfg.nvfp4;
        const bits = cfg.bits;
        const gs = cfg.gs;
        const mode: QuantMode = if (nvfp4) .nvfp4 else .affine;

        // Two independent banks, so a kernel that read the gate bank twice
        // could not pass.
        var banks: [2]struct { w: mlx.mlx_array, sc: mlx.mlx_array, bi: mlx.mlx_array } = undefined;
        var made: usize = 0;
        defer for (banks[0..made]) |b| {
            _ = mlx.mlx_array_free(b.w);
            _ = mlx.mlx_array_free(b.sc);
            if (b.bi.ctx != null) _ = mlx.mlx_array_free(b.bi);
        };
        for (0..2) |bi_idx| {
            const wb = try testRandWeightBf16(rnd, &[_]c_int{ E, N, K }, s);
            defer _ = mlx.mlx_array_free(wb);
            var triple = mlx.mlx_vector_array_new();
            defer _ = mlx.mlx_vector_array_free(triple);
            try mlx.check(mlx.mlx_quantize(&triple, wb, mlx.mlx_optional_int.some(@intCast(gs)), mlx.mlx_optional_int.some(@intCast(bits)), if (nvfp4) "nvfp4" else "affine", .{}, s));
            var wq = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_vector_array_get(&wq, triple, 0));
            var sc = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_vector_array_get(&sc, triple, 1));
            var bias = mlx.mlx_array{ .ctx = null };
            if (!nvfp4) {
                bias = mlx.mlx_array_new();
                try mlx.check(mlx.mlx_vector_array_get(&bias, triple, 2));
            }
            banks[bi_idx] = .{ .w = wq, .sc = sc, .bi = bias };
            made += 1;
        }

        const xbuf = try allocator.alloc(f32, @intCast(K));
        defer allocator.free(xbuf);
        for (xbuf) |*v| v.* = (rnd.float(f32) - 0.5) * 2.0;
        const xsh = [_]c_int{K};
        const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xsh, 1, .float32);
        defer _ = mlx.mlx_array_free(x32);
        var x = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(x);
        try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));

        var idx: [3]u32 = .{ 5, 0, 3 };
        const ish = [_]c_int{TOPK};
        const inds = mlx.mlx_array_new_data(&idx, &ish, 1, .uint32);
        defer _ = mlx.mlx_array_free(inds);

        // Reference: the two separate gathers, then the fused activation.
        const g2 = (try gatherQmv(s, x, banks[0].w, banks[0].sc, banks[0].bi, inds, bits, gs, mode, false)) orelse
            return error.GatherQmvDeclined;
        defer _ = mlx.mlx_array_free(g2);
        const up2 = (try gatherQmv(s, x, banks[1].w, banks[1].sc, banks[1].bi, inds, bits, gs, mode, false)) orelse
            return error.GatherQmvDeclined;
        defer _ = mlx.mlx_array_free(up2);
        const ref = (try fusedSwiGLU(s, g2, up2)) orelse return error.FusedSwigluDeclined;
        defer _ = mlx.mlx_array_free(ref);

        const got = (try gatherQmvGateUp(s, x, banks[0].w, banks[0].sc, banks[0].bi, banks[1].w, banks[1].sc, banks[1].bi, inds, bits, gs, mode, 0)) orelse
            return error.FusedGateUpDeclined;
        defer _ = mlx.mlx_array_free(got);
        // A swiglu_limit of 1 clamps these magnitudes: bit for bit clampedSwiGLU over the split gathers.
        const clamped = (try gatherQmvGateUp(s, x, banks[0].w, banks[0].sc, banks[0].bi, banks[1].w, banks[1].sc, banks[1].bi, inds, bits, gs, mode, 1)) orelse
            return error.FusedGateUpDeclined;
        defer _ = mlx.mlx_array_free(clamped);
        const clamp_ref = try clampedSwiGLU(s, g2, up2, 1.0);
        defer _ = mlx.mlx_array_free(clamp_ref);
        {
            var eq = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(eq);
            try mlx.check(mlx.mlx_array_equal(&eq, clamp_ref, clamped, false, s));
            try mlx.check(mlx.mlx_array_eval(eq));
            var eq_v = false;
            try mlx.check(mlx.mlx_array_item_bool(&eq_v, eq));
            try testing.expect(eq_v);
        }

        const cnt: usize = @intCast(TOPK * N);
        const ref_host = try allocator.alloc(f32, cnt);
        defer allocator.free(ref_host);
        const got_host = try allocator.alloc(f32, cnt);
        defer allocator.free(got_host);
        try testReadF32(ref, ref_host, s);
        try testReadF32(got, got_host, s);
        try testing.expectEqualSlices(f32, ref_host, got_host);
    }
}

fn moeRowsAffineBank(s: mlx.mlx_stream, rnd: std.Random, E: c_int, N: c_int, K: c_int, bits: u32, gs: u32) !struct { w: mlx.mlx_array, sc: mlx.mlx_array, bi: mlx.mlx_array } {
    const words: c_int = @intCast(@divExact(@as(u32, @intCast(K)) * bits, 32));
    const groups: c_int = @divExact(K, @as(c_int, @intCast(gs)));
    var key = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(key);
    try mlx.check(mlx.mlx_random_key(&key, rnd.int(u64)));
    const w_shape = [_]c_int{ E, N, words };
    var w = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_random_bits(&w, &w_shape, 3, 4, key, s));
    const s_shape = [_]c_int{ E, N, groups };
    const sc = try testRandUniformBf16(rnd, &s_shape, 0.01, 0.06, s);
    const bi = try testRandUniformBf16(rnd, &s_shape, -0.5, 0.5, s);
    return .{ .w = w, .sc = sc, .bi = bi };
}

fn moeRowsSliceRow(s: mlx.mlx_stream, x: mlx.mlx_array, i: c_int) !mlx.mlx_array {
    const sh = mlx.getShape(x);
    var start: [3]c_int = .{ i, 0, 0 };
    var stop: [3]c_int = .{ i + 1, 1, 1 };
    const strides = [_]c_int{ 1, 1, 1 };
    for (1..sh.len) |d| stop[d] = sh[d];
    var sl = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(sl);
    try mlx.check(mlx.mlx_slice(&sl, x, &start, @intCast(sh.len), &stop, @intCast(sh.len), &strides, @intCast(sh.len), s));
    var sq = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(sq);
    try mlx.check(mlx.mlx_squeeze(&sq, sl, s));
    return sq;
}

test "moe decode dispatch: rows vs sorted vs gatherQmv" {
    moe_rows_fused_override = true;
    defer moe_rows_fused_override = null;
    const K: c_int = 10;
    var b: c_int = 2;
    while (b <= 8) : (b += 1) {
        try std.testing.expectEqual(MoeDecodeDispatchArm.rows, moeDecodeDispatchArm(b, 1, K, false, false));
    }
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(9, 1, K, false, false));
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(2, 2, K, false, false));
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(2, 1, K, true, false));
    try std.testing.expectEqual(MoeDecodeDispatchArm.gather_qmv, moeDecodeDispatchArm(1, 1, K, false, false));
}

test "moe dispatch: a clamped SwiGLU declines the rows arm, at batched decode and at verify widths" {
    moe_rows_fused_override = true;
    defer moe_rows_fused_override = null;
    // The rows kernels apply no clamp (a limit of 10): the composed chain runs instead.
    try std.testing.expectEqual(MoeDecodeDispatchArm.rows, moeDecodeDispatchArm(4, 1, 10, false, false));
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(2, 1, 10, false, true));
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(8, 1, 10, false, true));
    try std.testing.expectEqual(MoeDecodeDispatchArm.rows, moeDecodeDispatchArm(1, 4, 10, false, false));
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(1, 4, 10, false, true));
}

test "moe decode dispatch: single-slot verify widths take the rows arm when enabled" {
    moe_verify_rows_override = true;
    defer moe_verify_rows_override = null;
    const K: c_int = 10;
    var s: c_int = 2;
    while (s <= 8) : (s += 1) {
        try std.testing.expectEqual(MoeDecodeDispatchArm.rows, moeDecodeDispatchArm(1, s, K, false, false));
    }
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(1, 9, K, false, false));
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(1, 4, K, true, false));
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(2, 4, K, false, false));
    moe_verify_rows_override = false;
    try std.testing.expectEqual(MoeDecodeDispatchArm.sorted, moeDecodeDispatchArm(1, 4, K, false, false));

    try std.testing.expect(moeVerifyRowsFor(null));
    try std.testing.expect(!moeVerifyRowsFor("0"));
    try std.testing.expect(moeVerifyRowsFor("1"));
}

test "gatherQmvGateUpRows accepts N=8 K=10" {
    const s = mlx.gpuStream();
    moe_rows_fused_override = true;
    defer moe_rows_fused_override = null;
    gqmv_gateup_override = true;
    defer gqmv_gateup_override = null;
    const nrows: c_int = 8;
    const topk: c_int = 10;
    const hid: c_int = 2560;
    const inter: c_int = 640;
    const E: c_int = 8;
    const bits: u32 = 4;
    const gs: u32 = 64;
    const xsh = [_]c_int{ nrows, hid };
    var x = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(x);
    try mlx.check(mlx.mlx_zeros(&x, &xsh, 2, .bfloat16, s));
    const ish = [_]c_int{ nrows, topk };
    var idata: [80]u32 = @splat(0);
    const inds = mlx.mlx_array_new_data(&idata, &ish, 2, .uint32);
    defer _ = mlx.mlx_array_free(inds);
    const wsh = [_]c_int{ E, inter, @intCast(@divExact(hid * @as(c_int, @intCast(bits)), 32)) };
    var gw = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gw);
    try mlx.check(mlx.mlx_zeros(&gw, &wsh, 3, .uint32, s));
    var uw = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(uw);
    try mlx.check(mlx.mlx_zeros(&uw, &wsh, 3, .uint32, s));
    const ssh = [_]c_int{ E, inter, @divExact(hid, @as(c_int, @intCast(gs))) };
    var gscl = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gscl);
    try mlx.check(mlx.mlx_zeros(&gscl, &ssh, 3, .bfloat16, s));
    var uscl = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(uscl);
    try mlx.check(mlx.mlx_zeros(&uscl, &ssh, 3, .bfloat16, s));
    var gb = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gb);
    try mlx.check(mlx.mlx_zeros(&gb, &ssh, 3, .bfloat16, s));
    var ub = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ub);
    try mlx.check(mlx.mlx_zeros(&ub, &ssh, 3, .bfloat16, s));
    const got = (try gatherQmvGateUpRows(s, x, gw, gscl, gb, uw, uscl, ub, inds, bits, gs, .affine, null)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(got);
}

test "moe rows fused: N=1 is byte-identical to the single-row kernel" {
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0x51F0);
    const rnd = prng.random();
    moe_rows_fused_override = true;
    defer moe_rows_fused_override = null;
    gqmv_gateup_override = true;
    defer gqmv_gateup_override = null;
    downred_override = true;
    defer downred_override = null;
    const E: c_int = 32;
    const hid: c_int = 2560;
    const inter: c_int = 640;
    const topk: c_int = 10;
    const bits: u32 = 4;
    const gs: u32 = 64;
    const gate = try moeRowsAffineBank(s, rnd, E, inter, hid, bits, gs);
    defer _ = mlx.mlx_array_free(gate.w);
    defer _ = mlx.mlx_array_free(gate.sc);
    defer _ = mlx.mlx_array_free(gate.bi);
    const up = try moeRowsAffineBank(s, rnd, E, inter, hid, bits, gs);
    defer _ = mlx.mlx_array_free(up.w);
    defer _ = mlx.mlx_array_free(up.sc);
    defer _ = mlx.mlx_array_free(up.bi);
    const down = try moeRowsAffineBank(s, rnd, E, hid, inter, 8, 32);
    defer _ = mlx.mlx_array_free(down.w);
    defer _ = mlx.mlx_array_free(down.sc);
    defer _ = mlx.mlx_array_free(down.bi);
    const x1 = try attn256RandBf16(rnd, &[_]c_int{hid}, s);
    defer _ = mlx.mlx_array_free(x1);
    var xrow = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(xrow);
    const xrsh = [_]c_int{ 1, hid };
    try mlx.check(mlx.mlx_reshape(&xrow, x1, &xrsh, 2, s));
    var idx: [10]u32 = .{ 0, 3, 7, 2, 11, 5, 9, 1, 4, 8 };
    const inds1 = mlx.mlx_array_new_data(&idx, &[_]c_int{topk}, 1, .uint32);
    defer _ = mlx.mlx_array_free(inds1);
    const inds2 = mlx.mlx_array_new_data(&idx, &[_]c_int{ 1, topk }, 2, .uint32);
    defer _ = mlx.mlx_array_free(inds2);
    const solo_gu = (try gatherQmvGateUp(s, x1, gate.w, gate.sc, gate.bi, up.w, up.sc, up.bi, inds1, bits, gs, .affine, 0)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(solo_gu);
    const rows_gu = (try gatherQmvGateUpRows(s, xrow, gate.w, gate.sc, gate.bi, up.w, up.sc, up.bi, inds2, bits, gs, .affine, null)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(rows_gu);
    var rows_gu_2d = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(rows_gu_2d);
    try mlx.check(mlx.mlx_squeeze(&rows_gu_2d, rows_gu, s));
    try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(solo_gu, rows_gu_2d, s));
    const scores1 = try attn256RandBf16(rnd, &[_]c_int{topk}, s);
    defer _ = mlx.mlx_array_free(scores1);
    var scores2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scores2);
    const scsh = [_]c_int{ 1, topk };
    try mlx.check(mlx.mlx_reshape(&scores2, scores1, &scsh, 2, s));
    const solo_dn = (try gatherQmvDownReduce(s, solo_gu, down.w, down.sc, down.bi, inds1, scores1, 8, 32, .affine)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(solo_dn);
    const rows_dn = (try gatherQmvDownReduceRows(s, rows_gu, down.w, down.sc, down.bi, inds2, scores2, 8, 32, .affine)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(rows_dn);
    var rows_dn_1d = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(rows_dn_1d);
    try mlx.check(mlx.mlx_squeeze(&rows_dn_1d, rows_dn, s));
    try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(solo_dn, rows_dn_1d, s));
}

test "moe rows fused: N=8 K=10 gate/up and down/reduce match N solo calls" {
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0xC0DE);
    const rnd = prng.random();
    moe_rows_fused_override = true;
    defer moe_rows_fused_override = null;
    gqmv_gateup_override = true;
    defer gqmv_gateup_override = null;
    downred_override = true;
    defer downred_override = null;
    const E: c_int = 512;
    const hid: c_int = 2560;
    const inter: c_int = 640;
    const topk: c_int = 10;
    const nrows: c_int = 8;
    for ([_]struct { bits: u32, gs: u32, dbits: u32, dgs: u32 }{
        .{ .bits = 4, .gs = 64, .dbits = 8, .dgs = 32 },
        .{ .bits = 3, .gs = 128, .dbits = 3, .dgs = 64 },
    }) |cfg| try moeRowsFusedCase(s, rnd, E, hid, inter, topk, nrows, cfg.bits, cfg.gs, cfg.dbits, cfg.dgs);
}

fn moeRowsFusedCase(s: mlx.mlx_stream, rnd: std.Random, E: c_int, hid: c_int, inter: c_int, topk: c_int, nrows: c_int, bits: u32, gs: u32, dbits: u32, dgs: u32) !void {
    const gate = try moeRowsAffineBank(s, rnd, E, inter, hid, bits, gs);
    defer _ = mlx.mlx_array_free(gate.w);
    defer _ = mlx.mlx_array_free(gate.sc);
    defer _ = mlx.mlx_array_free(gate.bi);
    const up = try moeRowsAffineBank(s, rnd, E, inter, hid, bits, gs);
    defer _ = mlx.mlx_array_free(up.w);
    defer _ = mlx.mlx_array_free(up.sc);
    defer _ = mlx.mlx_array_free(up.bi);
    const down = try moeRowsAffineBank(s, rnd, E, hid, inter, dbits, dgs);
    defer _ = mlx.mlx_array_free(down.w);
    defer _ = mlx.mlx_array_free(down.sc);
    defer _ = mlx.mlx_array_free(down.bi);
    const x = try attn256RandBf16(rnd, &[_]c_int{ nrows, hid }, s);
    defer _ = mlx.mlx_array_free(x);
    var idata: [80]u32 = undefined;
    const perm = [_]u32{ 0, 3, 0, 7, 2, 3, 5, 1 };
    for (0..8) |r| {
        const base = perm[r] * 17;
        for (0..10) |k| idata[r * 10 + k] = (base + @as(u32, @intCast(k)) * 13) % 512;
    }
    const inds = mlx.mlx_array_new_data(&idata, &[_]c_int{ nrows, topk }, 2, .uint32);
    defer _ = mlx.mlx_array_free(inds);
    const scores = try attn256RandBf16(rnd, &[_]c_int{ nrows, topk }, s);
    defer _ = mlx.mlx_array_free(scores);
    const fused_gu = (try gatherQmvGateUpRows(s, x, gate.w, gate.sc, gate.bi, up.w, up.sc, up.bi, inds, bits, gs, .affine, null)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(fused_gu);
    const fused_dn = (try gatherQmvDownReduceRows(s, fused_gu, down.w, down.sc, down.bi, inds, scores, dbits, dgs, .affine)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(fused_dn);
    var r: c_int = 0;
    while (r < nrows) : (r += 1) {
        const xr = try moeRowsSliceRow(s, x, r);
        defer _ = mlx.mlx_array_free(xr);
        const ir = try moeRowsSliceRow(s, inds, r);
        defer _ = mlx.mlx_array_free(ir);
        const sr = try moeRowsSliceRow(s, scores, r);
        defer _ = mlx.mlx_array_free(sr);
        const solo_gu = (try gatherQmvGateUp(s, xr, gate.w, gate.sc, gate.bi, up.w, up.sc, up.bi, ir, bits, gs, .affine, 0)) orelse return error.FusedDeclined;
        defer _ = mlx.mlx_array_free(solo_gu);
        const fused_r = try moeRowsSliceRow(s, fused_gu, r);
        defer _ = mlx.mlx_array_free(fused_r);
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(fused_r, solo_gu, s));
        const solo_dn = (try gatherQmvDownReduce(s, solo_gu, down.w, down.sc, down.bi, ir, sr, dbits, dgs, .affine)) orelse return error.FusedDeclined;
        defer _ = mlx.mlx_array_free(solo_dn);
        const fused_dr = try moeRowsSliceRow(s, fused_dn, r);
        defer _ = mlx.mlx_array_free(fused_dr);
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(fused_dr, solo_dn, s));
    }
}

test "moe rows fused nvfp4: verify rows with per-expert gate scales match fp32 truth" {
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0x4E5F);
    const rnd = prng.random();
    moe_rows_fused_override = true;
    defer moe_rows_fused_override = null;
    gqmv_gateup_override = true;
    defer gqmv_gateup_override = null;
    downred_override = true;
    defer downred_override = null;
    const E: c_int = 16;
    const H: c_int = 2560;
    const I: c_int = 640;
    const R: c_int = 5;
    const TOPK: c_int = 10;
    var tr = std.ArrayList(mlx.mlx_array).empty;
    defer {
        for (tr.items) |a| _ = mlx.mlx_array_free(a);
        tr.deinit(testing.allocator);
    }
    const P = struct {
        fn keep(list: *std.ArrayList(mlx.mlx_array), a: mlx.mlx_array) !mlx.mlx_array {
            try list.append(testing.allocator, a);
            return a;
        }
    };
    var banks: [3][2]mlx.mlx_array = undefined;
    var deq: [3]mlx.mlx_array = undefined;
    for (&banks, &deq, [3][3]c_int{ .{ E, I, H }, .{ E, I, H }, .{ E, H, I } }) |*b, *d, sh| {
        const w = try P.keep(&tr, try attn256RandBf16(rnd, &sh, s));
        var pair = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(pair);
        try mlx.check(mlx.mlx_quantize(&pair, w, mlx.mlx_optional_int.some(16), mlx.mlx_optional_int.some(4), "nvfp4", .{}, s));
        for (b, 0..) |*x, i| {
            x.* = mlx.mlx_array_new();
            try mlx.check(mlx.mlx_vector_array_get(x, pair, i));
            _ = try P.keep(&tr, x.*);
        }
        var dq = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_dequantize(&dq, b[0], b[1], .{ .ctx = null }, mlx.mlx_optional_int.some(16), mlx.mlx_optional_int.some(4), "nvfp4", .{ .ctx = null }, .{ .value = .float32, .has_value = true }, s));
        d.* = try P.keep(&tr, dq);
    }
    const gsc = try P.keep(&tr, try attn256RandBf16(rnd, &[_]c_int{E}, s));
    const x = try P.keep(&tr, try attn256RandBf16(rnd, &[_]c_int{ R, H }, s));
    const scores = try P.keep(&tr, try attn256RandBf16(rnd, &[_]c_int{ R, TOPK }, s));
    var idata: [R * TOPK]u32 = undefined;
    for (&idata, 0..) |*v, i| v.* = @intCast((i * 7 + i / 10) % 16);
    const inds = try P.keep(&tr, mlx.mlx_array_new_data(&idata, &[_]c_int{ R, TOPK }, 2, .uint32));

    const gu = (try gatherQmvGateUpRows(s, x, banks[0][0], banks[0][1], .{ .ctx = null }, banks[1][0], banks[1][1], .{ .ctx = null }, inds, 4, 16, .nvfp4, gsc)) orelse return error.FusedDeclined;
    _ = try P.keep(&tr, gu);
    const got = (try gatherQmvDownReduceRows(s, gu, banks[2][0], banks[2][1], .{ .ctx = null }, inds, scores, 4, 16, .nvfp4)) orelse return error.FusedDeclined;
    _ = try P.keep(&tr, got);

    // Truth in f32: per (row, slot) y += s * Wd (silu(gsc_e * Wg x) * Wu x).
    var a = mlx.mlx_array_new();
    const flat = blk: {
        try mlx.check(mlx.mlx_reshape(&a, inds, &.{R * TOPK}, 1, s));
        break :blk try P.keep(&tr, a);
    };
    var sel: [3]mlx.mlx_array = undefined;
    for (&sel, deq) |*o, d| {
        a = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_take_axis(&a, d, flat, 0, s));
        o.* = try P.keep(&tr, a);
    }
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_astype(&a, x, .float32, s));
    const x32 = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_reshape(&a, x32, &.{ R, 1, H, 1 }, 4, s));
    const x4 = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_broadcast_to(&a, x4, &.{ R, TOPK, H, 1 }, 4, s));
    const xb = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_reshape(&a, xb, &.{ R * TOPK, H, 1 }, 3, s));
    const xr = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_matmul(&a, sel[0], xr, s));
    const g = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_take_axis(&a, gsc, flat, 0, s));
    const ge = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_astype(&a, ge, .float32, s));
    const ge32 = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_reshape(&a, ge32, &.{ R * TOPK, 1, 1 }, 3, s));
    const ge3 = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_multiply(&a, g, ge3, s));
    const gs = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_sigmoid(&a, gs, s));
    const sg = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_multiply(&a, gs, sg, s));
    const silu = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_matmul(&a, sel[1], xr, s));
    const u = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_multiply(&a, silu, u, s));
    const act = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_matmul(&a, sel[2], act, s));
    const dn = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_astype(&a, scores, .float32, s));
    const s32 = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_reshape(&a, s32, &.{ R * TOPK, 1, 1 }, 3, s));
    const s3 = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_multiply(&a, dn, s3, s));
    const wd = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_reshape(&a, wd, &.{ R, TOPK, H }, 3, s));
    const wd3 = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_sum_axis(&a, wd3, 1, false, s));
    const truth = try P.keep(&tr, a);
    a = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_astype(&a, got, .float32, s));
    const got32 = try P.keep(&tr, a);
    try mlx.check(mlx.mlx_array_eval(truth));
    try mlx.check(mlx.mlx_array_eval(got32));
    const pt = mlx.mlx_array_data_float32(truth).?;
    const pg = mlx.mlx_array_data_float32(got32).?;
    var se: f64 = 0;
    var st: f64 = 0;
    for (0..@intCast(R * H)) |i| {
        se += (pg[i] - pt[i]) * (pg[i] - pt[i]);
        st += pt[i] * pt[i];
    }
    const rel = @sqrt(se / st);
    std.debug.print("[moe-rows] nvfp4 R={d} gate-scaled rel rms vs fp32 truth {d:.5}\n", .{ R, rel });
    try testing.expect(rel < 0.02);
}

