        const angles = try ropeAngleRow(s, 128, base, no_freqs, offset, std.testing.allocator);
        defer _ = mlx.mlx_array_free(angles);
        const pair = (try fusedQkNormRope(s, q, k, qw, kw, angles, null, eps_arr, hq, hk, 128)) orelse return error.FusedDeclined;
        defer _ = mlx.mlx_array_free(pair[0]);
        defer _ = mlx.mlx_array_free(pair[1]);

        const rq = try qkComposedRef(s, q, qw, null, hq, 128, base, no_freqs, offset, eps);
        defer _ = mlx.mlx_array_free(rq);
        const rk = try qkComposedRef(s, k, kw, null, hk, 128, base, no_freqs, offset, eps);
        defer _ = mlx.mlx_array_free(rk);

        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(pair[0], rq, s));
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(pair[1], rk, s));
    }
}

test "qk norm rope fused: rd=0 is the per-head norm alone, bit-identical to rms_norm + transpose (NoPE layers, 32q/4kv)" {
    const s = mlx.gpuStream();
    qk_fused_override = true;
    defer qk_fused_override = null;
    var prng = std.Random.DefaultPrng.init(0x0F17);
    const rnd = prng.random();
    const hq: c_int = 32;
    const hk: c_int = 4;
    const eps: f32 = 1.0e-6;
    const eps_arr = mlx.mlx_array_new_float(eps);
    defer _ = mlx.mlx_array_free(eps_arr);
    const q = try attn256RandBf16(rnd, &[_]c_int{ 1, 1, hq * 128 }, s);
    defer _ = mlx.mlx_array_free(q);
    const k = try attn256RandBf16(rnd, &[_]c_int{ 1, 1, hk * 128 }, s);
    defer _ = mlx.mlx_array_free(k);
    const qw = try attn256RandBf16(rnd, &[_]c_int{128}, s);
    defer _ = mlx.mlx_array_free(qw);
    const kw = try attn256RandBf16(rnd, &[_]c_int{128}, s);
    defer _ = mlx.mlx_array_free(kw);
    // No rotation reads the angles row; the norm weight binds in its place.
    const pair = (try fusedQkNormRope(s, q, k, qw, kw, qw, null, eps_arr, hq, hk, 0)) orelse return error.FusedDeclined;
    defer _ = mlx.mlx_array_free(pair[0]);
    defer _ = mlx.mlx_array_free(pair[1]);
    for ([_]struct { mlx.mlx_array, mlx.mlx_array, c_int, mlx.mlx_array }{ .{ q, qw, hq, pair[0] }, .{ k, kw, hk, pair[1] } }) |c| {
        var r = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(r);
        try mlx.check(mlx.mlx_reshape(&r, c[0], &[_]c_int{ 1, 1, c[2], 128 }, 4, s));
        var normed = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(normed);
        try mlx.check(mlx.mlx_fast_rms_norm(&normed, r, c[1], eps, s));
        var t = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(t);
        try mlx.check(mlx.mlx_transpose_axes(&t, normed, &[_]c_int{ 0, 2, 1, 3 }, 4, s));
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(c[3], t, s));
    }
}

test "qk norm rope fused: bit-identical incl. YaRN freqs + mscale (rd=64)" {
    const s = mlx.gpuStream();
    qk_fused_override = true;
    defer qk_fused_override = null;
    var prng = std.Random.DefaultPrng.init(0x40FF);
    const rnd = prng.random();

    const hq: c_int = 48;
    const hk: c_int = 8;
    const eps: f32 = 1.0e-6;
    const eps_arr = mlx.mlx_array_new_float(eps);
    defer _ = mlx.mlx_array_free(eps_arr);

    // YaRN-shaped freqs vector [rd/2] f32 and a removed-model shaped mscale table:
    // the YaRN factor on the rotated 64, exactly 1.0 on the pass-through tail.
    var freq_buf: [32]f32 = undefined;
    for (&freq_buf, 0..) |*f, i| f.* = std.math.pow(f32, 500000.0, @as(f32, @floatFromInt(i)) / 32.0);
    const f_shape = [_]c_int{32};
    const freqs = mlx.mlx_array_new_data(&freq_buf, &f_shape, 1, .float32);
    defer _ = mlx.mlx_array_free(freqs);
    const no_base = mlx.mlx_optional_float{ .value = 0, .has_value = false };

    var ms_buf: [128]f32 = undefined;
    for (&ms_buf, 0..) |*m, i| m.* = if (i < 64) 1.3465735912322998 else 1.0;
    const ms_shape = [_]c_int{128};
    const ms_f32 = mlx.mlx_array_new_data(&ms_buf, &ms_shape, 1, .float32);
    defer _ = mlx.mlx_array_free(ms_f32);
    var ms_bf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ms_bf);
    try mlx.check(mlx.mlx_astype(&ms_bf, ms_f32, .bfloat16, s));
    try mlx.check(mlx.mlx_array_eval(ms_bf));

    for ([_]c_int{ 0, 12345 }) |offset| {
        const q_shape = [_]c_int{ 1, 1, hq * 128 };
        const k_shape = [_]c_int{ 1, 1, hk * 128 };
        const w_shape = [_]c_int{128};
        const q = try attn256RandBf16(rnd, &q_shape, s);
        defer _ = mlx.mlx_array_free(q);
        const k = try attn256RandBf16(rnd, &k_shape, s);
        defer _ = mlx.mlx_array_free(k);
        const qw = try attn256RandBf16(rnd, &w_shape, s);
        defer _ = mlx.mlx_array_free(qw);
        const kw = try attn256RandBf16(rnd, &w_shape, s);
        defer _ = mlx.mlx_array_free(kw);

        const angles = try ropeAngleRow(s, 64, no_base, freqs, offset, std.testing.allocator);
        defer _ = mlx.mlx_array_free(angles);
        const pair = (try fusedQkNormRope(s, q, k, qw, kw, angles, ms_bf, eps_arr, hq, hk, 64)) orelse return error.FusedDeclined;
        defer _ = mlx.mlx_array_free(pair[0]);
        defer _ = mlx.mlx_array_free(pair[1]);

        const rq = try qkComposedRef(s, q, qw, ms_bf, hq, 64, no_base, freqs, offset, eps);
        defer _ = mlx.mlx_array_free(rq);
        const rk = try qkComposedRef(s, k, kw, ms_bf, hk, 64, no_base, freqs, offset, eps);
        defer _ = mlx.mlx_array_free(rk);

        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(pair[0], rq, s));
        try std.testing.expectEqual(@as(f32, 0.0), try attn256MaxDiff(pair[1], rk, s));
    }
}

// The YaRN `mscale != 1.0` arm registered only an `errdefer` for its `scaled` intermediate, so
// every successful call leaked one array per decode tick, each pinning its `MTLSharedEvent`,
// until the process wedged at the 65,535 cap. Settled residency is the observable.
test "ropeAngleRows hands back every array it builds, success path included" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const s = mlx.gpuStream();
    const allocator = testing.allocator;

    var freq_buf: [32]f32 = undefined;
    for (&freq_buf, 0..) |*f, i| f.* = std.math.pow(f32, 10000000.0, @as(f32, @floatFromInt(i)) / 32.0);
    const f_shape = [_]c_int{32};
    const freqs = mlx.mlx_array_new_data(&freq_buf, &f_shape, 1, .float32);
    defer _ = mlx.mlx_array_free(freqs);
    try mlx.check(mlx.mlx_array_eval(freqs));
    const no_base = mlx.mlx_optional_float{ .value = 0, .has_value = false };
    // Geometry: head_dim 256 x partial_rotary_factor 0.25.
    const rd: c_int = 64;

    // 1.0 is the unscaled arm; the second value is the YaRN attention factor at `factor: 4.0`.
    for ([_]f32{ 1.0, 1.1386294364929199 }) |mscale| {
        const c0 = mlx.op_count.load(.monotonic);
        const warm = try ropeAngleRows(s, rd, no_base, freqs, 0, 1, allocator, mscale, 1.0);
        const n_ops = mlx.op_count.load(.monotonic) - c0;
        try mlx.check(mlx.mlx_array_eval(warm));
        _ = mlx.mlx_array_free(warm);
        try testing.expect(n_ops >= 2);

        var k: u64 = 0;
        while (k <= n_ops) : (k += 1) {
            const base = mlxSettledActiveBytes(s);
            mlx.fault.arm(k); // arm(0) is a no-op arm: the SUCCESS path
            const r = ropeAngleRows(s, rd, no_base, freqs, @intCast(k + 1), 1, allocator, mscale, 1.0);
            mlx.fault.disarm();
            if (r) |a| {
                try mlx.check(mlx.mlx_array_eval(a));
                _ = mlx.mlx_array_free(a);
            } else |err| try testing.expectEqual(error.MlxError, err);
            const after = mlxSettledActiveBytes(s);
            if (after != base) std.debug.print(
                "[angle-rows] mscale={d} k={d}: base {d} after {d}\n",
                .{ mscale, k, base, after },
            );
            try testing.expectEqual(base, after);
        }
    }
}

test "no layer-init path DEMANDS quantization scales" {
    // Class guard, not an instance guard. A layer-init arm that fetches every
    // `.scales` with the mandatory getter aborts the load of a dense bf16
    // checkpoint ("MISSING WEIGHT: ….scales") while the standard and
    // MoE arms read absent scales as plain bf16. Any NEW arch arm
    // that reaches for scales the same way breaks dense checkpoints of that
    // arch, and nothing else would catch it - a quantized checkpoint of the
    // same arch loads fine either way.
    //
    // Needles are assembled at comptime: spelled whole they would match this
    // test's own source and the scan would satisfy itself.
    const src = @embedFile("transformer.zig");
    const mandatory = "getLayer" ++ "Weight(weights,";
    const optional = "getLayer" ++ "WeightOpt(weights,";
    const scales = ".scales" ++ "\")";
    try std.testing.expect(std.mem.indexOf(u8, src, optional) != null); // the scan can see a hit

    var it = std.mem.splitScalar(u8, src, '\n');
    var line_no: usize = 0;
    var checked: usize = 0;
    while (it.next()) |line| {
        line_no += 1;
        const trimmed = std.mem.trimStart(u8, line, " \t");
        if (std.mem.startsWith(u8, trimmed, "//")) continue; // prose, not code
        if (std.mem.indexOf(u8, line, scales) == null) continue;
        checked += 1;
        if (std.mem.indexOf(u8, line, mandatory) != null) {
            std.debug.print(
                "transformer.zig:{d} demands a scales tensor; dense bf16 ships none - use the optional getter\n",
                .{line_no},
            );
            return error.MandatoryScalesFetch;
        }
    }
    try std.testing.expect(checked > 20); // every arch arm's scales fetches
}

test "ownsModuleDecodeState is false while no module-owned arch exists" {
    // `module_owned_state_fields` is empty: no arch keeps per-request decode
    // state on a module shared by every slot. The predicate reads a NAMED LIST
    // so a future module-owned arch cannot drift from it; the class guard
    // below pins the list against the struct.
    var t: Transformer = undefined;
    t.rht = null;
    try testing.expect(!t.ownsModuleDecodeState());
}

test "every optional arch-module pointer on Transformer is a declared module-owned arch" {
    // Class guard, not an instance guard: a THIRD arch declared the same way
    // as the two above is module-owned by construction, and forgetting it in
    // the list is SILENT - serial decode still "works" until two clients
    // arrive at once. Needles are built at runtime so this test's own source
    // cannot satisfy its own scan.
    const src = @embedFile("transformer.zig");
    const opt_ptr = "?" ++ "*";
    const mod_dot = "_mod" ++ ".";
    var i: usize = 0;
    var found: usize = 0;
    while (std.mem.indexOfPos(u8, src, i, opt_ptr)) |p| {
        i = p + opt_ptr.len;
        // Shape: `    <name>: ?*<x>_mod.<Y> = null,` - the module type must
        // follow immediately, with a bare identifier in between.
        const rest = src[i..];
        const mod_at = std.mem.indexOf(u8, rest[0..@min(rest.len, 40)], mod_dot) orelse continue;
        if (std.mem.indexOfAny(u8, rest[0..mod_at], " ,)!*\"<`") != null) continue;
        const line_start = if (std.mem.lastIndexOfScalar(u8, src[0..p], '\n')) |nl| nl + 1 else 0;
        const decl = std.mem.trim(u8, src[line_start..p], " ");
        if (!std.mem.endsWith(u8, decl, ":")) continue;
        const name = decl[0 .. decl.len - 1];
        if (name.len == 0 or std.mem.indexOfAny(u8, name, " /(\"`") != null) continue;
        found += 1;
        var listed = false;
        for (Transformer.module_owned_state_fields) |f| {
            if (std.mem.eql(u8, f, name)) listed = true;
        }
        for (Transformer.module_shared_readonly_fields) |f| {
            if (std.mem.eql(u8, f, name)) listed = true;
        }
        if (!listed) {
            std.debug.print("module arch field declared in neither list: {s}\n", .{name});
            return error.UndeclaredModuleOwnedArch;
        }
    }
    // A scan that matches nothing passes vacuously - pin the known count.
    try testing.expectEqual(Transformer.module_owned_state_fields.len + Transformer.module_shared_readonly_fields.len, found);
}

test "every generative forward arm splices vision embeddings" {
    // `forwardWith` fans out to one arm per architecture family, and the
    // vision splice lives in each arm rather than above the fan-out. An arm
    // without one spliced NOTHING and the model answered from identical
    // `<image>` placeholder embeddings. Nothing errors in that failure; the
    // shapes, the token accounting and the encoder log line are all correct,
    // so it reads as a bad IMAGE rather than a missing splice.
    //
    // Every forward arm is required to splice, so a new arch cannot inherit the hole. A
    // text-only arm would be exempt BY NAME in the list below.
    const src = @embedFile("transformer.zig");
    const exempt = [_][]const u8{};
    const needle = "fn forward";
    var checked: usize = 0;
    var i: usize = 0;
    while (std.mem.indexOfPos(u8, src, i, needle)) |at| {
        i = at + needle.len;
        const line_end = std.mem.indexOfScalarPos(u8, src, at, '(') orelse continue;
        const name = src[at + 3 .. line_end]; // "forwardXWith"
        if (!std.mem.endsWith(u8, name, "With")) continue;
        if (std.mem.eql(u8, name, "forwardWith")) continue; // the dispatcher itself
        var is_exempt = false;
        for (exempt) |e| {
            if (std.mem.eql(u8, name, e)) is_exempt = true;
        }
        if (is_exempt) continue;
        // Each arm is well under 200 lines from its signature to the splice.
        const body_end = @min(src.len, at + 8000);
        const body = src[at..body_end];
        testing.expect(std.mem.indexOf(u8, body, "applyVisionEmbeddingsWith") != null) catch |e| {
            std.debug.print("{s} never calls applyVisionEmbeddingsWith\n", .{name});
            return e;
        };
        checked += 1;
    }
    // A scan that matches nothing passes vacuously: the standard and MoE forwards remain.
    try testing.expect(checked >= 2);
}

// ── Chunked vision splice (issue #197) ───────────────────────────────────────
// A vision prompt prefills in chunks; the splice's row lookup is a cumsum over
// the CURRENT forward's placeholder mask, so each chunk passes the rows earlier
// chunks consumed as `row_offset` - a restarted scatter silently reuses the
// first image rows in every chunk (coherent output, wrong image content).

test "spliceVisionRows: two chunks with row offsets equal the whole-prompt splice" {
    const s = mlx.mlx_default_gpu_stream_new();
    defer _ = mlx.mlx_stream_free(s);

    const hidden: c_int = 4;
    const seq: c_int = 6;
    const img_id: u32 = 99;
    // token ids: [7, 99, 99, 8, 99, 9] - placeholders at 1, 2 (chunk A) and 4
    // (chunk B), so the boundary lands INSIDE the image row sequence.
    const ids = [_]i32{ 7, 99, 99, 8, 99, 9 };
    // h rows: row i filled with i+1 (bf16-exact values).
    var h_data: [6 * 4]f32 = undefined;
    for (0..6) |r| for (0..4) |c| {
        h_data[r * 4 + c] = @floatFromInt(r + 1);
    };
    // vision rows: row k filled with 100+k - distinct per row, so a restarted
    // scatter (row 0 reused in chunk B) produces different bytes.
    var ve_data: [3 * 4]f32 = undefined;
    for (0..3) |r| for (0..4) |c| {
        ve_data[r * 4 + c] = @floatFromInt(100 + r);
    };
    const ve_shape = [_]c_int{ 1, 3, hidden };
    const ve = mlx.mlx_array_new_data(&ve_data, &ve_shape, 3, .float32);
    defer _ = mlx.mlx_array_free(ve);

    const readRow = struct {
        fn f(arr: mlx.mlx_array, row: usize, out: *[4]f32, st: mlx.mlx_stream) !void {
            var f32arr = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(f32arr);
            try mlx.check(mlx.mlx_astype(&f32arr, arr, .float32, st));
            try mlx.check(mlx.mlx_array_eval(f32arr));
            const ptr = mlx.mlx_array_data_float32(f32arr).?;
            for (0..4) |c| out[c] = ptr[row * 4 + c];
        }
    }.f;

    // Whole-prompt splice (the reference: what the unchunked path computes).
    var full_rows: [6][4]f32 = undefined;
    {
        const h_shape = [_]c_int{ 1, seq, hidden };
        const h = mlx.mlx_array_new_data(&h_data, &h_shape, 3, .float32);
        const ids_shape = [_]c_int{ 1, seq };
        const tid = mlx.mlx_array_new_data(&ids, &ids_shape, 2, .int32);
        defer _ = mlx.mlx_array_free(tid);
        const spliced = try Transformer.spliceVisionRows(h, tid, ve, img_id, 0, 0, 0, s);
        defer _ = mlx.mlx_array_free(spliced);
        for (0..6) |r| try readRow(spliced, r, &full_rows[r], s);
    }

    // Chunk A = tokens [0..3), offset 0; chunk B = tokens [3..6), offset 2
    // (chunk A consumed 2 placeholder rows).
    const chunks = [_]struct { start: usize, len: c_int, off: usize }{
        .{ .start = 0, .len = 3, .off = 0 },
        .{ .start = 3, .len = 3, .off = 2 },
    };
    for (chunks) |ck| {
        const h_shape = [_]c_int{ 1, ck.len, hidden };
        const h = mlx.mlx_array_new_data(h_data[ck.start * 4 ..].ptr, &h_shape, 3, .float32);
        const ids_shape = [_]c_int{ 1, ck.len };
        const tid = mlx.mlx_array_new_data(ids[ck.start..].ptr, &ids_shape, 2, .int32);
        defer _ = mlx.mlx_array_free(tid);
        const spliced = try Transformer.spliceVisionRows(h, tid, ve, img_id, 0, 0, ck.off, s);
        defer _ = mlx.mlx_array_free(spliced);
        for (0..@intCast(ck.len)) |r| {
            var got: [4]f32 = undefined;
            try readRow(spliced, r, &got, s);
            for (0..4) |c| try std.testing.expectEqual(full_rows[ck.start + r][c], got[c]);
        }
    }
}

test "spliceVisionRows: video placeholders are scattered like image rows (video_token_id)" {
    // Live 2026-08-26 (4-frame clip): 690 <|video_pad|> tokens were
    // inserted and the tower encoded 690 rows, but the mask keyed on image |
    // audio ids only, so no video row ever reached the prompt and the model
    // described a clip it never saw. Same hole (its e2e bar of
    // >= 2 of 4 generic subjects was passing on hallucination).
    const s = mlx.mlx_default_gpu_stream_new();
    defer _ = mlx.mlx_stream_free(s);
    const hidden: c_int = 4;
    const img_id: u32 = 99;
    const vid_id: u32 = 77;
    // [99, 7, 77, 77] - one image row, text, two video rows from ONE source.
    const ids = [_]i32{ 99, 7, 77, 77 };
    var h_data: [16]f32 = @splat(0);
    var ve_data: [3 * 4]f32 = undefined;
    for (0..3) |r| for (0..4) |c| {
        ve_data[r * 4 + c] = @floatFromInt(50 + r);
    };
    const ve_shape = [_]c_int{ 1, 3, hidden };
    const ve = mlx.mlx_array_new_data(&ve_data, &ve_shape, 3, .float32);
    defer _ = mlx.mlx_array_free(ve);
    const h_shape = [_]c_int{ 1, 4, hidden };
    const h = mlx.mlx_array_new_data(&h_data, &h_shape, 3, .float32);
    const ids_shape = [_]c_int{ 1, 4 };
    const tid = mlx.mlx_array_new_data(&ids, &ids_shape, 2, .int32);
    defer _ = mlx.mlx_array_free(tid);
    const spliced = try Transformer.spliceVisionRows(h, tid, ve, img_id, 0, vid_id, 0, s);
    defer _ = mlx.mlx_array_free(spliced);
    var f32arr = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(f32arr);
    try mlx.check(mlx.mlx_astype(&f32arr, spliced, .float32, s));
    try mlx.check(mlx.mlx_array_eval(f32arr));
    const ptr = mlx.mlx_array_data_float32(f32arr).?;
    try std.testing.expectEqual(@as(f32, 50), ptr[0]); // image row 0
    try std.testing.expectEqual(@as(f32, 0), ptr[4]); // text untouched
    try std.testing.expectEqual(@as(f32, 51), ptr[8]); // video row 1
    try std.testing.expectEqual(@as(f32, 52), ptr[12]); // video row 2
}

