/// Bit equality of two strided views (cache slices are not row-contiguous).
fn ringViewsEqual(s: mlx.mlx_stream, a: mlx.mlx_array, b: mlx.mlx_array) !bool {
    const ca = try materializedOwnedCopy(s, a);
    defer _ = mlx.mlx_array_free(ca);
    const cb = try materializedOwnedCopy(s, b);
    defer _ = mlx.mlx_array_free(cb);
    return bf16BitsEqual(ca, cb);
}

test "KVCache restore: a restored entry exposes its live rows to a read before the first update" {
    if (mlx.noGpuBackend()) return error.SkipZigTest;
    const s = mlx.gpuStream();
    var prng = std.Random.DefaultPrng.init(0x7E57);
    var src = try KVCache.init(testing.allocator, 1);
    defer src.deinit();
    const k = try testRandWeightBf16(prng.random(), &.{ 1, 1, 25, 8 }, s);
    defer _ = mlx.mlx_array_free(k);
    const v = try testRandWeightBf16(prng.random(), &.{ 1, 1, 25, 4 }, s);
    defer _ = mlx.mlx_array_free(v);
    var first = try src.update(0, k, v, s, 0);
    first.deinit();
    var snap = try src.snapshot();
    defer snap.deinit();

    // A DSA layer reads the cached rows BEFORE it appends (the previous indexer rows for pooling).
    var back = try KVCache.init(testing.allocator, 1);
    defer back.deinit();
    try back.restore(&snap);
    const view = try back.denseView(0, s);
    try testing.expect(view.k.ctx != null and view.v.ctx != null);
    try testing.expectEqual(@as(c_int, 25), mlx.getShape(view.k)[2]);
    try testing.expectEqual(@as(c_int, 25), mlx.getShape(view.v)[2]);
    try testing.expect(try ringViewsEqual(s, view.k, k));
}

/// The fp4 MoE decode kernels read no expert biases, and apply a SwiGLU clamp only as a whole-number
/// limit: a pack with a bias, or `clamp` null (`swigluClampLimit`: a clamp no kernel serves), keeps the
/// composed chain, as does an activation that is not 16-bit (the SwiGLU table covers 16-bit patterns).
/// The kernels apply SiLU only: a GELU model (`hidden_act`) keeps the composed chain.
fn moeFp4DecodeEligible(rows: c_int, has_expert_bias: bool, clamp: ?u32, hidden_act: model_mod.HiddenAct, act: mlx.mlx_dtype, gate: model_mod.QuantMode, up: model_mod.QuantMode, down: model_mod.QuantMode) bool {
    return rows <= moe_fp4.MAX_ROWS and !has_expert_bias and clamp != null and hidden_act == .silu and (act == .bfloat16 or act == .float16) and (gate == .mxfp4 or gate == .nvfp4) and up == gate and down == gate;
}

test "moe fp4 decode: expert biases or a clamp no kernel serves keep the composed chain" {
    var cfg: ModelConfig = undefined;
    cfg.swiglu_limit = 0;
    try testing.expectEqual(@as(?u32, 0), swigluClampLimit(&cfg));
    cfg.swiglu_limit = 10;
    try testing.expectEqual(@as(?u32, null), swigluClampLimit(&cfg));
    try testing.expect(moeFp4DecodeEligible(1, false, 0, .silu, .bfloat16, .mxfp4, .mxfp4, .mxfp4));
    try testing.expect(!moeFp4DecodeEligible(1, true, 0, .silu, .bfloat16, .mxfp4, .mxfp4, .mxfp4));
    try testing.expect(moeFp4DecodeEligible(1, false, 10, .silu, .bfloat16, .nvfp4, .nvfp4, .nvfp4));
    // An f32 stream (an f32 norm weight upstream) has no sigmoid table: decline, never throw.
    try testing.expect(!moeFp4DecodeEligible(1, false, 0, .silu, .float32, .mxfp4, .mxfp4, .mxfp4));
    try testing.expect(moeFp4DecodeEligible(1, false, 0, .silu, .float16, .mxfp4, .mxfp4, .mxfp4));
    try testing.expect(!moeFp4DecodeEligible(1, false, null, .silu, .bfloat16, .mxfp4, .mxfp4, .mxfp4));
    try testing.expect(!moeFp4DecodeEligible(1, false, 0, .silu, .bfloat16, .affine, .mxfp4, .mxfp4));
    try testing.expect(moeFp4DecodeEligible(1, false, 0, .silu, .bfloat16, .nvfp4, .nvfp4, .nvfp4));
    try testing.expect(!moeFp4DecodeEligible(1, false, 0, .silu, .bfloat16, .nvfp4, .mxfp4, .nvfp4));
    // A GELU model keeps the composed chain: the kernels apply SiLU only.
    try testing.expect(!moeFp4DecodeEligible(1, false, 0, .gelu_approx, .bfloat16, .mxfp4, .mxfp4, .mxfp4));
    try testing.expect(!moeFp4DecodeEligible(moe_fp4.MAX_ROWS + 1, false, 0, .silu, .bfloat16, .mxfp4, .mxfp4, .mxfp4));
}

